replay_harness.source:
#!/usr/bin/env python3
"""Black-box quick-fix qualification for a supplied hoonarqube CLI binary.

This harness is deliberately outside the repository.  It reads the current
quick-fix manifests when invoked, creates one disposable application directory
per language/rule/action, and records enough evidence to audit every decision:
commands, streams, reports, source hashes, native edit projections, and final
source bytes.  It never treats an unavailable prerequisite or a missing action
as a successful skip.
"""

from __future__ import annotations

import argparse
import ast
import hashlib
import json
import os
import re
import shutil
import signal
import subprocess
import sys
from pathlib import Path
from typing import Any, Iterable
from xml.sax.saxutils import escape as xml_escape


SCHEMA_VERSION = 1
DEFAULT_TIMEOUT_SECONDS = 90
JSTS_DERIVED_OVERLAY = "jsts-quickfix-derived-overlay.json"
PYTHON_MANIFEST = "python-quickfix-cases.json"
CSHARP_MANIFEST = "csharp-quickfix-cases.json"
LANGUAGES = ("python", "javascript", "typescript", "csharp")
LANGUAGE_ALIASES = {
    "py": "python",
    "python": "python",
    "js": "javascript",
    "javascript": "javascript",
    "ts": "typescript",
    "typescript": "typescript",
    "c#": "csharp",
    "cs": "csharp",
    "csharp": "csharp",
}
SDK_ONLY_NUGET_CONFIG = "<?xml version=\"1.0\" encoding=\"utf-8\"?>\n<configuration><packageSources><clear /></packageSources></configuration>\n"
DEFAULT_CSHARP_OUTPUT_TYPE = "Library"
DEFAULT_CSHARP_FRAMEWORK_REFERENCES: tuple[str, ...] = ()


class HarnessError(Exception):
    """A fatal harness setup or manifest error."""


def sha256_bytes(value: bytes) -> str:
    return hashlib.sha256(value).hexdigest()


def sha256_file(path: Path) -> str:
    try:
        return sha256_bytes(path.read_bytes())
    except OSError:
        return ""


def write_bytes(path: Path, value: bytes) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_bytes(value)


def write_text(path: Path, value: str) -> None:
    write_bytes(path, value.encode("utf-8"))


def write_json(path: Path, value: Any) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(
        json.dumps(value, ensure_ascii=False, indent=2, sort_keys=True) + "\n",
        encoding="utf-8",
        newline="",
    )


def read_json(path: Path) -> Any:
    return json.loads(path.read_text(encoding="utf-8"))


def slug(value: str, limit: int = 100) -> str:
    result = re.sub(r"[^A-Za-z0-9_.-]+", "_", value).strip("_.-")
    return (result or "item")[:limit]


def relpath(path: Path, root: Path) -> str:
    try:
        return os.path.relpath(path, root).replace(os.sep, "/")
    except ValueError:
        return str(path).replace(os.sep, "/")


def decode_output(value: bytes) -> str:
    return value.decode("utf-8", errors="replace")


def path_key(value: Any) -> str:
    return os.path.normcase(os.path.normpath(str(value).replace("\\", "/"))).replace("\\", "/")


def safe_manifest_path(raw: Any) -> Path:
    if not isinstance(raw, str) or not raw:
        raise HarnessError(f"manifest project file path is not a nonempty string: {raw!r}")
    path = Path(raw)
    if path.is_absolute() or any(part in {"", ".", ".."} for part in path.parts):
        raise HarnessError(f"manifest project file path is not a safe relative path: {raw!r}")
    return path


def parse_selector_values(values: list[str]) -> list[str]:
    selectors: list[str] = []
    for value in values:
        selectors.extend(item.strip() for item in value.split(",") if item.strip())
    return selectors


def report_files(report: Any) -> list[dict[str, Any]]:
    if not isinstance(report, dict) or not isinstance(report.get("files"), list):
        return []
    return [item for item in report["files"] if isinstance(item, dict)]


def report_project_complete(report: Any) -> bool | None:
    if not isinstance(report, dict):
        return None
    project = report.get("project")
    if not isinstance(project, dict):
        return None
    value = project.get("complete")
    return value if isinstance(value, bool) else None


def file_path_matches(value: Any, expected: Path, workspace: Path) -> bool:
    if not isinstance(value, str):
        return False
    actual = path_key(value)
    expected_abs = path_key(expected)
    if actual == expected_abs:
        return True
    try:
        expected_rel = path_key(expected.relative_to(workspace))
    except ValueError:
        expected_rel = ""
    if expected_rel and (actual == expected_rel or actual.endswith("/" + expected_rel)):
        return True
    return actual.endswith("/" + path_key(expected.name))


def matching_report_files(report: Any, expected: Path, workspace: Path) -> list[dict[str, Any]]:
    return [item for item in report_files(report) if file_path_matches(item.get("path"), expected, workspace)]


def issue_rule_counts(report: Any) -> dict[str, int]:
    counts: dict[str, int] = {}
    for item in report_files(report):
        issues = item.get("issues")
        if not isinstance(issues, list):
            continue
        for issue in issues:
            if isinstance(issue, dict) and isinstance(issue.get("rule_key"), str):
                rule = issue["rule_key"]
                counts[rule] = counts.get(rule, 0) + 1
    return counts


def issue_matches_rule(issue: Any, rule_key: str) -> bool:
    return isinstance(issue, dict) and issue.get("rule_key") == rule_key


def find_issues(report: Any, rule_key: str, workspace: Path, target_path: Path | None = None) -> list[tuple[dict[str, Any], dict[str, Any]]]:
    found: list[tuple[dict[str, Any], dict[str, Any]]] = []
    for item in report_files(report):
        if target_path is not None and not file_path_matches(item.get("path"), target_path, workspace):
            continue
        issues = item.get("issues")
        if not isinstance(issues, list):
            continue
        for issue in issues:
            if issue_matches_rule(issue, rule_key):
                found.append((item, issue))
    return found


def codepoint_offset(source: str, line: Any, column: Any) -> int:
    if not isinstance(line, int) or not isinstance(column, int) or line < 1 or column < 0:
        raise HarnessError(f"invalid native source position line={line!r} column={column!r}")
    starts = [0]
    for index, character in enumerate(source):
        if character == "\n":
            starts.append(index + 1)
    if line == len(starts) + 1 and column == 0 and source.endswith("\n"):
        return len(source)
    if line > len(starts):
        raise HarnessError(f"source position line {line} is outside {len(starts)} lines")
    offset = starts[line - 1] + column
    if offset > len(source):
        raise HarnessError(f"source position column {column} is outside source line {line}")
    return offset


def range_offsets(source: str, value: Any) -> tuple[int, int]:
    if not isinstance(value, dict):
        raise HarnessError(f"native edit range is not an object: {value!r}")
    start = value.get("start")
    end = value.get("end")
    if not isinstance(start, dict) or not isinstance(end, dict):
        raise HarnessError(f"native edit range lacks start/end: {value!r}")
    first = codepoint_offset(source, start.get("line"), start.get("column"))
    last = codepoint_offset(source, end.get("line"), end.get("column"))
    if first > last:
        raise HarnessError(f"native edit range is inverted: {value!r}")
    return first, last


def apply_native_edits(source: str, edits: Any) -> str:
    if not isinstance(edits, list) or not edits:
        raise HarnessError("finding fix has no edits")
    converted: list[tuple[int, int, str]] = []
    for edit in edits:
        if not isinstance(edit, dict) or not isinstance(edit.get("replacement"), str):
            raise HarnessError(f"malformed native TextEdit: {edit!r}")
        first, last = range_offsets(source, edit.get("range"))
        converted.append((first, last, edit["replacement"]))
    converted.sort(key=lambda item: (item[0], item[1]))
    for previous, current in zip(converted, converted[1:]):
        if current[0] < previous[1] or (current[0] == current[1] == previous[0] == previous[1]):
            raise HarnessError("native TextEdits overlap")
    projected = source
    for first, last, replacement in reversed(converted):
        projected = projected[:first] + replacement + projected[last:]
    return projected
def compose_native_fixes(fixes: Iterable[dict[str, Any]]) -> dict[str, Any]:
    """Compose independently reported fixes without hiding overlapping edits.

    Multi-finding controls may only collapse byte-for-byte identical edits.
    Distinct overlapping edits remain in the composed list and are rejected by
    ``apply_native_edits`` rather than being silently selected or rewritten.
    """
    composed: list[dict[str, Any]] = []
    seen_edits: set[str] = set()
    message = ""
    for fix in fixes:
        if not isinstance(fix, dict):
            raise HarnessError(f"native multi-finding fix is not an object: {fix!r}")
        if not message and isinstance(fix.get("message"), str):
            message = fix["message"]
        edits = fix.get("edits")
        if not isinstance(edits, list) or not edits:
            raise HarnessError(f"native multi-finding fix has no edits: {fix!r}")
        for edit in edits:
            if not isinstance(edit, dict) or not isinstance(edit.get("replacement"), str):
                raise HarnessError(f"native multi-finding edit is malformed: {edit!r}")
            key = json.dumps(
                [edit.get("range"), edit.get("replacement")],
                sort_keys=True,
                separators=(",", ":"),
            )
            if key not in seen_edits:
                seen_edits.add(key)
                composed.append(edit)
    if not composed:
        raise HarnessError("native multi-finding fixes have no edits")
    return {"message": message, "edits": composed}


def selected_csharp_positive_case(row: Any, action_id: str | None) -> dict[str, Any] | None:
    if not isinstance(row, dict) or not isinstance(action_id, str):
        return None
    positives = row.get("positive_cases")
    if not isinstance(positives, list):
        return None
    matches = [
        item
        for item in positives
        if isinstance(item, dict) and item.get("action_id") == action_id
    ]
    return matches[0] if len(matches) == 1 else None
def reference_no_action_evidence(
    artifact_path: Path | None,
    artifact_sha256: Any,
    selector: Any,
    rule: str,
    action_id: str,
    source_hashes: dict[str, str],
) -> dict[str, Any]:
    """Resolve a frozen provider fixture and return its recorded no-action facts."""
    result: dict[str, Any] = {
        "artifact_present": bool(artifact_path and artifact_path.is_file()),
        "artifact_sha256": artifact_sha256,
        "observed_artifact_sha256": sha256_file(artifact_path) if artifact_path else "",
        "artifact_sha256_matches": False,
        "selector_valid": False,
        "selector_contains_source": False,
        "rule": rule,
        "action_id": action_id,
        "fixture_kind": None,
        "fixture_source_path": None,
        "fixture_source_sha256": None,
        "fixture_source_hash_matches": False,
        "target_diagnostic_count": None,
        "provider_candidate_count": None,
        "offered_action_count": None,
        "availability": None,
        "errors": [],
    }
    errors = result["errors"]
    if not result["artifact_present"]:
        errors.append("reference artifact is unavailable")
        return result
    if not isinstance(artifact_sha256, str) or not artifact_sha256:
        errors.append("reference artifact SHA-256 is missing")
    else:
        result["artifact_sha256_matches"] = (
            result["observed_artifact_sha256"] == artifact_sha256
        )
        if not result["artifact_sha256_matches"]:
            errors.append("reference artifact SHA-256 does not match")
    selector_bounds: tuple[int, int] | None = None
    if not isinstance(selector, str):
        errors.append("reference selector is missing")
    else:
        selector_match = re.fullmatch(r"([1-9][0-9]*)-([1-9][0-9]*)", selector)
        if selector_match:
            first, last = (int(value) for value in selector_match.groups())
            try:
                line_count = len(artifact_path.read_bytes().splitlines()) if artifact_path else 0
            except OSError:
                line_count = 0
            result["selector_valid"] = first <= last <= line_count
            if result["selector_valid"]:
                selector_bounds = (first, last)
        if not result["selector_valid"]:
            errors.append("reference selector is outside the artifact")
    try:
        artifact = read_json(artifact_path)
    except (OSError, UnicodeDecodeError, json.JSONDecodeError) as exc:
        errors.append(f"reference artifact cannot be parsed: {exc}")
        return result
    if not isinstance(artifact, dict) or not isinstance(artifact.get("cases"), list):
        errors.append("reference artifact has no cases array")
        return result
    candidates = [
        case
        for case in artifact["cases"]
        if isinstance(case, dict)
        and case.get("rule") == rule
        and action_id in (case.get("declared_action_ids") or [])
    ]
    fixtures: list[dict[str, Any]] = []
    for case in candidates:
        values = case.get("fixtures")
        if isinstance(values, list):
            fixtures.extend(item for item in values if isinstance(item, dict))
    matched_fixture: dict[str, Any] | None = None
    matched_source: dict[str, Any] | None = None
    for fixture in fixtures:
        provenance = fixture.get("source_provenance")
        if not isinstance(provenance, list):
            continue
        for source in provenance:
            if not isinstance(source, dict):
                continue
            logical_path = source.get("logical_path")
            source_hash = source.get("source_sha256")
            for declared_path, declared_hash in source_hashes.items():
                if (
                    isinstance(logical_path, str)
                    and path_key(logical_path) == path_key(declared_path)
                    and source_hash == declared_hash
                ):
                    matched_fixture = fixture
                    matched_source = source
                    break
            if matched_fixture is not None:
                break
        if matched_fixture is not None:
            break
    if matched_fixture is None or matched_source is None:
        errors.append("control source is absent from the selected reference fixture")
        return result
    result["fixture_kind"] = matched_fixture.get("fixture_kind")
    result["fixture_source_path"] = matched_source.get("logical_path")
    result["fixture_source_sha256"] = matched_source.get("source_sha256")
    if selector_bounds is not None:
        first, last = selector_bounds
        try:
            artifact_lines = artifact_path.read_bytes().splitlines() if artifact_path else []
        except OSError:
            artifact_lines = []
        source_marker = str(matched_source.get("source_sha256") or "").encode("ascii")
        result["selector_contains_source"] = any(
            first <= line_number <= last and source_marker and source_marker in line
            for line_number, line in enumerate(artifact_lines, start=1)
        )
        if not result["selector_contains_source"]:
            errors.append("reference selector does not contain the matched source fixture")
    result["fixture_source_hash_matches"] = True
    per_actions = matched_fixture.get("per_declared_action")
    if not isinstance(per_actions, list):
        errors.append("reference fixture has no per-declared-action facts")
        return result
    action_facts = [
        item
        for item in per_actions
        if isinstance(item, dict) and item.get("declared_action_id") == action_id
    ]
    if len(action_facts) != 1:
        errors.append("reference fixture does not have one selected action fact")
        return result
    facts = action_facts[0]
    for result_key, source_key in (
        ("target_diagnostic_count", "target_diagnostic_count"),
        ("provider_candidate_count", "provider_candidate_count"),
        ("offered_action_count", "offered_action_count"),
        ("availability", "availability"),
    ):
        result[result_key] = facts.get(source_key)
    return result





def normalize_edits(edits: Any) -> list[dict[str, Any]]:
    if not isinstance(edits, list):
        return []
    return [item for item in edits if isinstance(item, dict)]


def selected_fix(issue: dict[str, Any], action_id: str | None, automatic: bool) -> tuple[dict[str, Any] | None, str | None]:
    if automatic:
        fix = issue.get("fix")
        return (fix if isinstance(fix, dict) else None), None
    alternatives = issue.get("alternatives")
    if not isinstance(alternatives, list):
        return None, "issue has no alternatives"
    matches = [item for item in alternatives if isinstance(item, dict) and item.get("id") == action_id]
    if len(matches) != 1:
        return None, f"expected exactly one alternative {action_id!r}, found {len(matches)}"
    fix = matches[0].get("fix")
    return (fix if isinstance(fix, dict) else None), None


def concrete_expected(value: Any, source: str | None = None) -> bool:
    """Check projection syntax without requiring Python 3 syntax in the original source."""
    if not isinstance(value, str) or not value:
        return False
    if source is not None and not isinstance(source, str):
        return False
    try:
        ast.parse(value, filename="<expected-projection>", mode="exec")
    except (SyntaxError, TypeError, ValueError):
        return False
    prose_markers = (
        "statement removed",
        "and all same-class",
        "(or pass",
        "and sequence targets",
        "(and ",
    )
    return not any(marker in value for marker in prose_markers)

def nonnegative_int(value: Any) -> bool:
    return isinstance(value, int) and not isinstance(value, bool) and value >= 0

def reference_fix_shape(value: Any) -> str | None:
    """Return the concrete reference-fix encoding, or None for malformed data."""
    if not isinstance(value, dict) or not value:
        return None
    edits = value.get("edits")
    if isinstance(edits, list) and edits:
        top_range = value.get("range")
        if (
            not isinstance(top_range, list)
            or len(top_range) != 2
            or not all(nonnegative_int(item) for item in top_range)
            or top_range[0] > top_range[1]
            or not isinstance(value.get("text"), str)
        ):
            return None
        for edit in edits:
            if not isinstance(edit, dict):
                return None
            span = edit.get("range")
            if (
                not isinstance(span, list)
                or len(span) != 2
                or not all(nonnegative_int(item) for item in span)
                or span[0] > span[1]
                or not isinstance(edit.get("text"), str)
            ):
                return None
        return "edits"
    span = value.get("range")
    if isinstance(span, dict):
        utf16_range = span.get("utf16_range")
        if (
            isinstance(utf16_range, list)
            and len(utf16_range) == 2
            and all(nonnegative_int(item) for item in utf16_range)
            and utf16_range[0] <= utf16_range[1]
            and isinstance(value.get("text"), str)
            and isinstance(value.get("projected"), str)
        ):
            return "utf16_range"
        return None
    if (
        isinstance(span, list)
        and len(span) == 2
        and all(nonnegative_int(item) for item in span)
        and span[0] <= span[1]
        and isinstance(value.get("text"), str)
    ):
        return "range_text"
    return None

def mechanical_fixed(source: str) -> str:
    """Mirror the CLI's language-agnostic final-newline repair."""
    if not source or source.endswith("\n"):
        return source
    uses_crlf = "\n" in source and source.rfind("\n") > 0 and source[source.rfind("\n") - 1] == "\r"
    return source + ("\r" if uses_crlf and not source.endswith("\r") else "") + "\n"



def selected_plan_rows(parsed: Any, workspace: Path, target_paths: Iterable[Path]) -> list[dict[str, Any]]:
    paths = list(target_paths)
    rows = parsed.get("files") if isinstance(parsed, dict) else None
    if not isinstance(rows, list):
        return []
    result: list[dict[str, Any]] = []
    for row in rows:
        if not isinstance(row, dict):
            continue
        if any(file_path_matches(row.get("path"), path, workspace) for path in paths):
            result.append(row)
    return result


def plan_fix_entries(parsed: Any, workspace: Path, target_paths: Iterable[Path]) -> list[dict[str, Any]]:
    entries: list[dict[str, Any]] = []
    for row in selected_plan_rows(parsed, workspace, target_paths):
        fixes = row.get("fixes")
        if isinstance(fixes, list):
            entries.extend(item for item in fixes if isinstance(item, dict))
    return entries


def plan_has_action(parsed: Any, workspace: Path, target_paths: Iterable[Path], expected_edits: Any | None = None) -> bool:
    entries = plan_fix_entries(parsed, workspace, target_paths)
    if expected_edits is None:
        return bool(entries)
    expected = normalize_edits(expected_edits)
    return any(normalize_edits(item.get("edits")) == expected for item in entries)

def plan_has_declared_action(
    parsed: Any,
    workspace: Path,
    target_paths: Iterable[Path],
    rule_key: str,
    action_id: str,
) -> bool:
    """Detect only the requested rule/action, ignoring unrelated file fixes."""
    for row in selected_plan_rows(parsed, workspace, target_paths):
        alternatives = row.get("alternatives")
        fixes = row.get("fixes")
        if not isinstance(alternatives, list) or not isinstance(fixes, list):
            continue
        selected = [
            item
            for item in alternatives
            if isinstance(item, dict)
            and item.get("id") == action_id
            and item.get("rule_key") == rule_key
        ]
        for alternative in selected:
            nested = alternative.get("alternative")
            expected_fix = nested.get("fix") if isinstance(nested, dict) else None
            if not isinstance(expected_fix, dict):
                continue
            expected_edits = normalize_edits(expected_fix.get("edits"))
            if any(
                isinstance(fix, dict)
                and fix.get("rule_key") == rule_key
                and normalize_edits(fix.get("edits")) == expected_edits
                for fix in fixes
            ):
                return True
    return False


def plan_alternatives(parsed: Any, workspace: Path, target_paths: Iterable[Path]) -> list[dict[str, Any]]:
    result: list[dict[str, Any]] = []
    for row in selected_plan_rows(parsed, workspace, target_paths):
        values = row.get("alternatives")
        if isinstance(values, list):
            result.extend(item for item in values if isinstance(item, dict))
    return result


def file_hashes(paths: Iterable[Path]) -> dict[str, str]:
    return {str(path): sha256_file(path) for path in paths}


class CommandRunner:
    """Runs bounded commands and writes exact streams to an application dir."""

    def __init__(self, binary: Path, output_root: Path, timeout: int) -> None:
        self.binary = binary
        self.output_root = output_root
        self.timeout = timeout

    def invoke(
        self,
        app_dir: Path,
        label: str,
        command: list[str],
        cwd: Path,
        parse_json: bool = True,
        extra_env: dict[str, str] | None = None,
    ) -> dict[str, Any]:
        invocation_dir = app_dir / "invocations" / slug(label)
        invocation_dir.mkdir(parents=True, exist_ok=True)
        exact_command = [str(value) for value in command]
        write_json(invocation_dir / "command.json", {"argv": exact_command, "cwd": str(cwd), "timeout_seconds": self.timeout})
        environment = os.environ.copy()
        environment.update(
            {
                "DOTNET_CLI_TELEMETRY_OPTOUT": "1",
                "DOTNET_SKIP_FIRST_TIME_EXPERIENCE": "1",
                "DOTNET_NOLOGO": "1",
                "NUGET_XMLDOC_MODE": "skip",
                "DOTNET_CLI_HOME": str(app_dir / "dotnet-home"),
            }
        )
        if extra_env:
            environment.update(extra_env)
        stdout = b""
        stderr = b""
        returncode: int | None = None
        timed_out = False
        error: str | None = None
        try:
            process = subprocess.Popen(
                exact_command,
                cwd=str(cwd),
                env=environment,
                stdin=subprocess.DEVNULL,
                stdout=subprocess.PIPE,
                stderr=subprocess.PIPE,
                start_new_session=True,
            )
            try:
                stdout, stderr = process.communicate(timeout=self.timeout)
                returncode = process.returncode
            except subprocess.TimeoutExpired as exc:
                timed_out = True
                error = f"timed out after {self.timeout} seconds"
                if exc.stdout:
                    stdout = exc.stdout
                if exc.stderr:
                    stderr = exc.stderr
                try:
                    os.killpg(process.pid, signal.SIGKILL)
                except ProcessLookupError:
                    pass
                remaining_out, remaining_err = process.communicate()
                stdout += remaining_out
                stderr += remaining_err
                returncode = process.returncode
        except OSError as exc:
            error = f"could not execute command: {exc}"
        stdout_path = invocation_dir / "stdout.bin"
        stderr_path = invocation_dir / "stderr.bin"
        stdout_path.write_bytes(stdout)
        stderr_path.write_bytes(stderr)
        record: dict[str, Any] = {
            "label": label,
            "argv": exact_command,
            "cwd": str(cwd),
            "returncode": returncode,
            "timed_out": timed_out,
            "stdout_path": relpath(stdout_path, self.output_root),
            "stderr_path": relpath(stderr_path, self.output_root),
            "stdout_sha256": sha256_bytes(stdout),
            "stderr_sha256": sha256_bytes(stderr),
            "stdout_bytes": len(stdout),
            "stderr_bytes": len(stderr),
        }
        if error is not None:
            record["error"] = error
        parsed: Any = None
        if parse_json:
            if stdout:
                try:
                    parsed = json.loads(decode_output(stdout))
                    parsed_path = invocation_dir / "parsed.json"
                    write_json(parsed_path, parsed)
                    record["parsed_path"] = relpath(parsed_path, self.output_root)
                except (json.JSONDecodeError, UnicodeDecodeError) as exc:
                    record["parse_error"] = f"stdout is not one JSON document: {exc}"
            else:
                record["parse_error"] = "stdout is empty"
        record["parsed"] = parsed
        return record

    def cli(
        self,
        app_dir: Path,
        label: str,
        args: list[str],
        cwd: Path,
    ) -> dict[str, Any]:
        return self.invoke(app_dir, label, [str(self.binary), *args], cwd, parse_json=True)


class Application:
    def __init__(
        self,
        harness: "Harness",
        language: str,
        row_index: int,
        rule_key: str,
        action_id: str | None,
        mode: str,
        row: dict[str, Any],
    ) -> None:
        self.harness = harness
        self.language = language
        self.row_index = row_index
        self.rule_key = rule_key
        self.action_id = action_id
        self.mode = mode
        self.row = row
        name = f"{row_index:03d}-{slug(rule_key)}-{slug(action_id or mode)}"
        self.app_dir = harness.output_root / "applications" / language / name
        if self.app_dir.exists():
            shutil.rmtree(self.app_dir)
        self.app_dir.mkdir(parents=True, exist_ok=True)
        self.workspace = self.app_dir / "workspace"
        self.workspace.mkdir(parents=True, exist_ok=True)
        self.invocations: list[dict[str, Any]] = []
        self.failures: list[str] = []
        self.unavailable: list[str] = []
        self.explicit_status: str | None = None
        self.positive_paths: list[Path] = []
        self.negative_paths: list[Path] = []
        self.target_path: Path | None = None
        self.semantic_args: list[str] = []
        self.project_path: Path | None = None
        self.nuget_config: Path | None = None
        self.csharp_header_format: str | None = None
        self.tsconfig: Path | None = None
        self.source_before: dict[str, str] = {}
        self.source_after: dict[str, str] = {}
        self.record: dict[str, Any] = {
            "schema_version": SCHEMA_VERSION,
            "language": language,
            "row_index": row_index,
            "rule_key": rule_key,
            "action_id": action_id,
            "mode": mode,
            "status": "running",
            "application_dir": relpath(self.app_dir, harness.output_root),
            "workspace": relpath(self.workspace, harness.output_root),
            "failures": self.failures,
            "unavailable": self.unavailable,
            "invocations": [],
            "checks": {},
        }
        write_json(self.app_dir / "manifest-row.json", row)

    def fail(self, message: str) -> None:
        self.failures.append(message)

    def mark_unavailable(self, message: str) -> None:
        self.unavailable.append(message)

    def invoke_cli(self, label: str, args: list[str]) -> dict[str, Any]:
        result = self.harness.runner.cli(self.app_dir, label, args, self.workspace)
        self.invocations.append(result)
        self.record["invocations"] = [self.harness.invocation_public(item) for item in self.invocations]
        return result

    def invoke_command(self, label: str, command: list[str], cwd: Path, parse_json: bool = False) -> dict[str, Any]:
        result = self.harness.runner.invoke(self.app_dir, label, command, cwd, parse_json=parse_json)
        self.invocations.append(result)
        self.record["invocations"] = [self.harness.invocation_public(item) for item in self.invocations]
        return result

    def save_report(self, label: str, report: Any) -> str | None:
        if report is None:
            return None
        path = self.app_dir / f"{slug(label)}-report.json"
        write_json(path, report)
        return relpath(path, self.harness.output_root)

    def save_source_snapshot(self, label: str, paths: Iterable[Path]) -> None:
        values: dict[str, Any] = {}
        for path in paths:
            try:
                content = path.read_bytes()
                values[relpath(path, self.workspace)] = {
                    "path": relpath(path, self.harness.output_root),
                    "sha256": sha256_bytes(content),
                    "bytes": len(content),
                    "source": content.decode("utf-8", errors="replace"),
                }
            except OSError as exc:
                values[relpath(path, self.workspace)] = {"error": str(exc), "sha256": ""}
        write_json(self.app_dir / f"{slug(label)}-sources.json", values)

    def finalize(self) -> dict[str, Any]:
        if self.failures:
            self.record["status"] = "fail"
        elif self.unavailable:
            self.record["status"] = "unavailable"
        elif self.explicit_status is not None:
            self.record["status"] = self.explicit_status
        else:
            self.record["status"] = "pass"
        self.record["failures"] = list(self.failures)
        self.record["unavailable"] = list(self.unavailable)
        write_json(self.app_dir / "application-result.json", self.record)
        return self.record


class Harness:
    def __init__(self, args: argparse.Namespace) -> None:
        self.args = args
        self.script_dir = Path(__file__).resolve().parent
        self.manifest_root = self.script_dir.parent
        self.output_root = Path(args.output).expanduser().resolve()
        self.output_root.mkdir(parents=True, exist_ok=True)
        self.binary = Path(args.binary).expanduser()
        if not self.binary.is_absolute():
            raise HarnessError("--binary must be an absolute path")
        self.binary = self.binary.resolve()
        if not self.binary.is_file() or not os.access(self.binary, os.X_OK):
            raise HarnessError(f"--binary is not an executable regular file: {self.binary}")
        self.timeout = args.timeout
        self.runner = CommandRunner(self.binary, self.output_root, self.timeout)
        self.selectors = parse_selector_values(args.rule)
        self.language = LANGUAGE_ALIASES.get(args.language) if args.language else None
        if args.language and self.language is None:
            raise HarnessError(f"unsupported --language value: {args.language!r}")
        self.applications: list[dict[str, Any]] = []
        self.top_failures: list[str] = []
        self.manifest_records: dict[str, dict[str, Any]] = {}
        self.typescript_module = self.resolve_typescript_module()
        self.typescript_base = self.resolve_typescript_base()
        self.dotnet = self.resolve_dotnet()

    def invocation_public(self, invocation: dict[str, Any]) -> dict[str, Any]:
        return {key: value for key, value in invocation.items() if key != "parsed"}

    def resolve_typescript_module(self) -> Path | None:
        values = []
        if os.environ.get("HOONARQUBE_TYPESCRIPT_MODULE"):
            values.append(Path(os.environ["HOONARQUBE_TYPESCRIPT_MODULE"]))
        values.extend(
            [
                Path("/tmp/hoonarqube-jsrefs.ClOXQC/node_modules/typescript"),
                Path.cwd() / "node_modules" / "typescript",
            ]
        )
        for candidate in values:
            candidate = candidate.expanduser().resolve()
            package = candidate / "package.json"
            try:
                metadata = read_json(package)
            except (OSError, json.JSONDecodeError):
                continue
            if isinstance(metadata, dict) and metadata.get("name") == "typescript" and metadata.get("version") == "6.0.3":
                return candidate
        return None

    def resolve_typescript_base(self) -> Path | None:
        candidates = [
            Path.cwd() / "crates" / "hoonarqube-jsts" / "fixtures" / "semantic" / "tsconfig.base.json",
            self.manifest_root / "tsconfig.base.json",
        ]
        for candidate in candidates:
            if candidate.is_file():
                return candidate.resolve()
        return None

    def resolve_dotnet(self) -> Path | None:
        value = os.environ.get("HOONARQUBE_DOTNET")
        candidate = Path(value).expanduser() if value else None
        if candidate is None:
            found = shutil.which("dotnet")
            candidate = Path(found) if found else None
        if candidate is None:
            return None
        candidate = candidate.resolve()
        return candidate if candidate.is_file() and os.access(candidate, os.X_OK) else None

    def load_manifest(self, filename: str, language: str) -> list[dict[str, Any]]:
        path = self.manifest_root / filename
        try:
            raw = path.read_bytes()
            value = json.loads(raw.decode("utf-8"))
        except (OSError, UnicodeDecodeError, json.JSONDecodeError) as exc:
            raise HarnessError(f"cannot load {path}: {exc}") from exc
        if not isinstance(value, list):
            raise HarnessError(f"{path} must contain a JSON array")
        if not value:
            self.top_failures.append(f"{language}: manifest is empty")
        self.manifest_records[language] = {
            "path": str(path),
            "sha256": sha256_bytes(raw),
            "bytes": len(raw),
            "rows": len(value),
        }
        rows: list[dict[str, Any]] = []
        for index, item in enumerate(value):
            if not isinstance(item, dict):
                self.top_failures.append(f"{language} row {index}: manifest entry is not an object")
                continue
            rows.append(item)
        return rows

    def rule_selected(self, language: str, row: dict[str, Any], rule_key: str) -> bool:
        if not self.selectors:
            return True
        values = {
            str(row.get("rule", "")),
            str(row.get("key", "")),
            str(row.get("target_rule", "")),
            rule_key,
        }
        suffix = rule_key.split(":", 1)[-1]
        values.add(suffix)
        return any(any(value.lower() == selector.lower() or value.lower().startswith(selector.lower()) for value in values) for selector in self.selectors)

    def semantic_args_for(self, app: Application) -> list[str]:
        if app.language == "csharp":
            if app.project_path is None:
                return []
            return ["--csharp-project", relpath(app.project_path, app.workspace), "--allow-project-build"]
        if app.language == "typescript":
            if app.tsconfig is None or self.typescript_module is None:
                return []
            return [
                "--typescript-project",
                relpath(app.tsconfig, app.workspace),
                "--typescript-module",
                str(self.typescript_module),
            ]
        if app.language == "python" and (
            app.row.get("python_require_type_hints") is True
            or app.rule_key == "python:S6538"
        ):
            return ["--python-require-type-hints"]
        return []
    def csharp_option_args(self, app: Application) -> list[str]:
        if app.language != "csharp" or not app.csharp_header_format:
            return []
        return ["--csharp-header-format", app.csharp_header_format]

    def analyzer_args(self, paths: list[Path], app: Application) -> list[str]:
        return [
            "analyze",
            "--profile",
            "sonar-parity",
            "--format",
            "json",
            *app.semantic_args,
            *self.csharp_option_args(app),
            *[relpath(path, app.workspace) for path in paths],
        ]

    def fix_args(
        self,
        paths: list[Path],
        app: Application,
        automatic: bool,
        apply: bool,
    ) -> list[str]:
        args = ["--json", "fix"]
        if automatic:
            args.extend(["--rule", app.rule_key])
        else:
            if app.action_id is None:
                raise HarnessError("suggestion application has no action id")
            args.extend(["--suggestion", f"{app.rule_key}={app.action_id}"])
        args.append("--diff")
        if apply:
            args.append("--apply")
        args.extend(app.semantic_args)
        args.extend(self.csharp_option_args(app))
        args.extend(relpath(path, app.workspace) for path in paths)
        return args

    def prepare_ts(self, app: Application, source_paths: list[Path]) -> None:
        if self.typescript_module is None:
            app.mark_unavailable("pinned TypeScript 6.0.3 module is unavailable; expected /tmp/hoonarqube-jsrefs.ClOXQC/node_modules/typescript or HOONARQUBE_TYPESCRIPT_MODULE")
            return
        if self.typescript_base is None:
            app.mark_unavailable("pinned TypeScript tsconfig.base.json is unavailable")
            return
        write_bytes(app.workspace / "tsconfig.base.json", self.typescript_base.read_bytes())
        app.tsconfig = app.workspace / "tsconfig.json"
        config: dict[str, Any] = {
            "extends": "./tsconfig.base.json",
            "files": [relpath(path, app.workspace) for path in source_paths],
        }
        case_reference = app.row.get("_case_reference")
        reference_config = (
            case_reference.get("config")
            if isinstance(case_reference, dict)
            else None
        )
        compiler_options = (
            reference_config.get("compilerOptions")
            if isinstance(reference_config, dict)
            else None
        )
        if isinstance(compiler_options, dict):
            config["compilerOptions"] = compiler_options
        write_json(app.tsconfig, config)
        app.semantic_args = self.semantic_args_for(app)

    def prepare_csharp(
        self,
        app: Application,
        paths: list[Path],
        project_context: Any = None,
    ) -> None:
        if self.dotnet is None:
            app.mark_unavailable("installed dotnet SDK is unavailable")
            return
        context = {} if project_context is None else project_context
        if not isinstance(context, dict):
            app.fail("CSharp project_context must be an object")
            return
        output_type = context.get("output_type", DEFAULT_CSHARP_OUTPUT_TYPE)
        if output_type not in {"Library", "Exe", "WinExe"}:
            app.fail(f"CSharp project_context output_type is invalid: {output_type!r}")
            return
        framework_references = context.get(
            "framework_references",
            list(DEFAULT_CSHARP_FRAMEWORK_REFERENCES),
        )
        if (
            not isinstance(framework_references, list)
            or any(not isinstance(value, str) or not value for value in framework_references)
        ):
            app.fail("CSharp project_context framework_references must be nonempty strings")
            return
        header_format = context.get("csharp_header_format")
        if header_format is not None and not isinstance(header_format, str):
            app.fail("CSharp project_context csharp_header_format must be a string")
            return
        implicit_usings = context.get("implicit_usings", False)
        if not isinstance(implicit_usings, bool):
            app.fail("CSharp project_context implicit_usings must be a boolean")
            return
        language_version = context.get("language_version")
        if language_version is not None and (
            not isinstance(language_version, str) or not language_version
        ):
            app.fail("CSharp project_context language_version must be a nonempty string")
            return
        app.csharp_header_format = header_format or None
        config_source = self.manifest_root / "helper-smoke" / "NuGet.Config"
        app.nuget_config = app.workspace / "NuGet.Config"
        try:
            config_bytes = config_source.read_bytes() if config_source.is_file() else SDK_ONLY_NUGET_CONFIG.encode("utf-8")
            write_bytes(app.nuget_config, config_bytes)
        except OSError as exc:
            app.mark_unavailable(f"cannot materialize offline NuGet.Config: {exc}")
            return
        app.project_path = app.workspace / "Fixture.csproj"
        framework_xml = "".join(
            f"<FrameworkReference Include=\"{xml_escape(value)}\" />"
            for value in framework_references
        )
        framework_group = f"<ItemGroup>{framework_xml}</ItemGroup>" if framework_xml else ""
        implicit_usings_xml = (
            "<ImplicitUsings>enable</ImplicitUsings>" if implicit_usings else ""
        )
        language_version_xml = (
            f"<LangVersion>{xml_escape(language_version)}</LangVersion>"
            if language_version is not None
            else ""
        )
        project = (
            "<Project Sdk=\"Microsoft.NET.Sdk\">"
            "<PropertyGroup><TargetFramework>net10.0</TargetFramework>"
            f"<OutputType>{xml_escape(output_type)}</OutputType>"
            f"{implicit_usings_xml}{language_version_xml}"
            "<Nullable>enable</Nullable>"
            "<EnableDefaultCompileItems>true</EnableDefaultCompileItems>"
            "<Deterministic>true</Deterministic></PropertyGroup>"
            f"{framework_group}</Project>"
        )
        write_text(app.project_path, project)
        context_name = (
            "negative"
            if app.workspace == app.app_dir / "negative" / "workspace"
            else "positive"
        )
        app.record["checks"].setdefault("csharp_project_context", {})[context_name] = {
            "target_framework": "net10.0",
            "output_type": output_type,
            "framework_references": list(framework_references),
            "csharp_header_format": header_format or "",
            "header_option_present": bool(header_format),
            "implicit_usings": implicit_usings,
            "language_version": language_version,
            "project_path": relpath(app.project_path, self.output_root),
        }
        app.semantic_args = self.semantic_args_for(app)
        restore = self.invoke_dotnet_restore(app)
        if restore.get("returncode") != 0:
            app.fail(f"offline SDK-only CSharp restore failed with exit code {restore.get('returncode')!r}")

    def invoke_dotnet_restore(self, app: Application) -> dict[str, Any]:
        if self.dotnet is None or app.project_path is None or app.nuget_config is None:
            raise HarnessError("CSharp restore requested before project setup")
        return app.invoke_command(
            "dotnet-restore",
            [
                str(self.dotnet),
                "restore",
                str(app.project_path),
                "--configfile",
                str(app.nuget_config),
                "--ignore-failed-sources",
                "--disable-parallel",
                "--nologo",
            ],
            app.workspace,
            parse_json=False,
        )

    def materialize_python(self, app: Application) -> bool:
        source = app.row.get("fixture_source")
        if not isinstance(source, str):
            app.fail("manifest fixture_source is missing or not a string")
            return False
        if app.action_id:
            actions = app.row.get("actions")
            if isinstance(actions, list):
                for action in actions:
                    if isinstance(action, dict) and action.get("id") == app.action_id and isinstance(action.get("action_fixture_source"), str):
                        source = action["action_fixture_source"]
                        break
        target = app.workspace / "src" / "case.py"
        write_text(target, source)
        app.positive_paths = [target]
        app.target_path = target
        app.source_before = file_hashes(app.positive_paths)
        app.save_source_snapshot("initial", app.positive_paths)
        return True

    def materialize_jsts(self, app: Application) -> bool:
        source = app.row.get("source")
        project_files = app.row.get("project_files")
        if not isinstance(source, str):
            if (
                isinstance(project_files, list)
                and project_files
                and isinstance(project_files[0], dict)
                and isinstance(project_files[0].get("source"), str)
            ):
                source = project_files[0]["source"]
            else:
                app.fail("manifest source is missing or not a string")
                return False
        case_reference = app.row.get("_case_reference")
        expected_source_hash = case_reference.get("source_sha256") if isinstance(case_reference, dict) else None
        if isinstance(expected_source_hash, str) and sha256_bytes(source.encode("utf-8")) != expected_source_hash:
            app.fail("manifest source_sha256 does not match source text")
        suffix = ".ts" if app.language == "typescript" else ".js"
        paths: list[Path] = []
        if isinstance(project_files, list) and project_files:
            for item in project_files:
                if not isinstance(item, dict) or not isinstance(item.get("source"), str):
                    app.fail(f"project file lacks a string source: {item!r}")
                    continue
                try:
                    relative = safe_manifest_path(item.get("path"))
                except HarnessError as exc:
                    app.fail(str(exc))
                    continue
                target = app.workspace / relative
                write_text(target, item["source"])
                paths.append(target)
        else:
            raw_path = app.row.get("path")
            try:
                relative = safe_manifest_path(raw_path) if isinstance(raw_path, str) else Path(f"src/case{suffix}")
            except HarnessError as exc:
                app.fail(str(exc))
                return False
            target = app.workspace / relative
            write_text(target, source)
            paths.append(target)
        if not paths:
            app.fail("manifest JSTS case has no materialized project files")
            return False
        app.positive_paths = paths
        app.target_path = paths[0]
        raw_path = app.row.get("path")
        if isinstance(raw_path, str):
            matching = [
                path
                for path in paths
                if path_key(raw_path) in {path_key(relpath(path, app.workspace)), path_key(path.name)}
            ]
            if len(matching) == 1:
                app.target_path = matching[0]
        if app.language == "typescript" and isinstance(project_files, list) and project_files:
            self.prepare_ts(app, paths)
        app.source_before = file_hashes(app.positive_paths)
        app.save_source_snapshot("initial", app.positive_paths)
        return True

    def materialize_csharp_files(self, app: Application, project_files: Any, label: str) -> list[Path]:
        if not isinstance(project_files, list) or not project_files:
            app.fail(f"{label}: project_files is missing or empty")
            return []
        paths: list[Path] = []
        for item in project_files:
            if not isinstance(item, dict) or not isinstance(item.get("source"), str):
                app.fail(f"{label}: project file lacks a string source: {item!r}")
                continue
            try:
                relative = safe_manifest_path(item.get("path"))
            except HarnessError as exc:
                app.fail(f"{label}: {exc}")
                continue
            target = app.workspace / relative
            write_text(target, item["source"])
            paths.append(target)
        return paths

    def materialize_csharp(self, app: Application, positive: dict[str, Any]) -> bool:
        paths = self.materialize_csharp_files(app, positive.get("project_files"), "positive")
        app.positive_paths = paths
        if not paths:
            return False
        app.target_path = paths[0]
        target_hint = positive.get("path") or positive.get("source_path") or app.row.get("source_path")
        if isinstance(target_hint, str):
            matching = [
                path
                for path in paths
                if path_key(target_hint) in {path_key(relpath(path, app.workspace)), path_key(path.name)}
            ]
            if len(matching) == 1:
                app.target_path = matching[0]
        self.prepare_csharp(app, paths, positive.get("project_context"))
        provenance = positive.get("reference_provenance")
        if isinstance(provenance, dict):
            artifact = provenance.get("artifact")
            artifact_path = (
                self.manifest_root / artifact
                if isinstance(artifact, str) and not Path(artifact).is_absolute()
                else None
            )
            source_hash = sha256_file(paths[0])
            observed_artifact_hash = sha256_file(artifact_path) if artifact_path else ""
            expected_artifact_hash = provenance.get("sha256")
            expected_source_hash = provenance.get("source_sha256")
            app.record["checks"]["reference_provenance"] = {
                "artifact": artifact,
                "selector": provenance.get("selector"),
                "status": provenance.get("status"),
                "expected_sha256": expected_artifact_hash,
                "observed_sha256": observed_artifact_hash,
                "source_sha256": source_hash,
                "expected_source_sha256": expected_source_hash,
                "expected_final_source_sha256": provenance.get("final_source_sha256"),
                "reference_final_source_sha256": provenance.get(
                    "reference_final_source_sha256"
                ),
                "note": provenance.get("note"),
            }
            if (
                isinstance(expected_artifact_hash, str)
                and expected_artifact_hash
                and observed_artifact_hash != expected_artifact_hash
            ):
                app.fail("CSharp reference provenance artifact hash mismatch")
            if (
                isinstance(expected_source_hash, str)
                and expected_source_hash
                and source_hash != expected_source_hash
            ):
                app.fail("CSharp reference provenance source hash mismatch")
        app.source_before = file_hashes(paths)
        app.save_source_snapshot("initial", paths)
        return True

    def materialize_negative(self, app: Application) -> bool:
        negative = app.row.get("negative")
        if app.language in {"python", "javascript", "typescript"}:
            if not isinstance(negative, str):
                app.record["checks"]["negative"] = {
                    "status": "not_exercised",
                    "reason": "negative is not an actual source fixture",
                }
                return False
            # The Python matrix's negative values are prose guards.  Do not
            # execute them as if they were source; this is intentional.
            if app.language == "python":
                app.record["checks"]["negative"] = {
                    "status": "not_exercised_prose",
                    "reason": "manifest negative is prose-only",
                }
                return False
            negative_dir = app.app_dir / "negative"
            negative_workspace = negative_dir / "workspace"
            negative_workspace.mkdir(parents=True, exist_ok=True)
            suffix = ".ts" if app.language == "typescript" else ".js"
            path = negative_workspace / "src" / f"case{suffix}"
            write_text(path, negative)
            app.negative_paths = [path]
            # Negative workspaces need their own semantic project files.
            if app.language == "typescript" and isinstance(app.row.get("project_files"), list) and app.row.get("project_files"):
                old_workspace, old_tsconfig, old_semantic = app.workspace, app.tsconfig, app.semantic_args
                app.workspace = negative_workspace
                app.tsconfig = negative_workspace / "tsconfig.json"
                self.prepare_ts(app, [path])
                negative_semantic = app.semantic_args
                app.workspace, app.tsconfig, app.semantic_args = old_workspace, old_tsconfig, old_semantic
                app.record["checks"]["negative_semantic_args"] = negative_semantic
            return True
        if app.language == "csharp":
            if not isinstance(negative, dict):
                app.fail("negative CSharp fixture is not an object")
                return False
            negative_dir = app.app_dir / "negative"
            negative_workspace = negative_dir / "workspace"
            negative_workspace.mkdir(parents=True, exist_ok=True)
            old_workspace = app.workspace
            app.workspace = negative_workspace
            paths = self.materialize_csharp_files(app, negative.get("project_files"), "negative")
            app.negative_paths = paths
            self.prepare_csharp(app, paths, negative.get("project_context"))
            app.workspace = old_workspace
            return bool(paths)
        return False

    def semantic_args_for_negative(self, app: Application) -> list[str]:
        negative_workspace = app.app_dir / "negative" / "workspace"
        if app.language == "typescript":
            config = negative_workspace / "tsconfig.json"
            if self.typescript_module is None or not config.is_file():
                return []
            return ["--typescript-project", "tsconfig.json", "--typescript-module", str(self.typescript_module)]
        if app.language == "csharp":
            project = negative_workspace / "Fixture.csproj"
            if not project.is_file():
                return []
            return ["--csharp-project", "Fixture.csproj", "--allow-project-build"]
        return []

    def compiler_diagnostic_warnings(self, report: Any) -> list[str]:
        if not isinstance(report, dict):
            return []
        project = report.get("project")
        warnings = project.get("warnings") if isinstance(project, dict) else None
        if not isinstance(warnings, list):
            return []
        return [
            warning
            for warning in warnings
            if isinstance(warning, str) and "compiler_diagnostic:" in warning
        ]

    def expected_diagnostic_gate(
        self,
        report: Any,
        expected: Any,
    ) -> dict[str, Any] | None:
        if expected is None:
            return None
        actual = self.compiler_diagnostic_warnings(report)
        if not isinstance(expected, list) or not expected:
            return {
                "status": "INVALID_EXPECTATION",
                "expected": expected,
                "actual": actual,
                "matches": False,
                "missing": expected if isinstance(expected, list) else [],
                "unexpected": actual,
            }
        used: set[int] = set()
        missing: list[Any] = []
        matched: list[dict[str, Any]] = []
        for item in expected:
            if (
                not isinstance(item, dict)
                or not isinstance(item.get("code"), str)
                or not item["code"]
                or not isinstance(item.get("path"), str)
                or not item["path"]
            ):
                missing.append(item)
                continue
            code = item["code"].upper()
            expected_path = item.get("path")
            expected_path_key = path_key(expected_path) if isinstance(expected_path, str) else None
            expected_line = item.get("line")
            expected_column = item.get("column")
            found_index: int | None = None
            for index, warning in enumerate(actual):
                if index in used or f"ERROR {code}:" not in warning.upper():
                    continue
                diagnostic = warning.split("compiler_diagnostic:", 1)[-1].strip()
                warning_path = diagnostic.split("(", 1)[0].strip()
                if expected_path_key is not None:
                    warning_path_key = path_key(warning_path)
                    if not (
                        warning_path_key == expected_path_key
                        or warning_path_key.endswith("/" + expected_path_key)
                        or warning_path_key.endswith(expected_path_key)
                    ):
                        continue
                location = re.search(r"\((\d+),(\d+)\):", diagnostic)
                if isinstance(expected_line, int) and (
                    location is None or int(location.group(1)) != expected_line
                ):
                    continue
                if isinstance(expected_column, int) and (
                    location is None or int(location.group(2)) != expected_column
                ):
                    continue
                found_index = index
                break
            if found_index is None:
                missing.append(item)
            else:
                used.add(found_index)
                matched.append({"expected": item, "warning": actual[found_index]})
        unexpected = [warning for index, warning in enumerate(actual) if index not in used]
        return {
            "status": (
                "EXPECTED_COMPILER_DIAGNOSTICS"
                if not missing and not unexpected
                else "UNEXPECTED_COMPILER_DIAGNOSTICS"
            ),
            "expected": expected,
            "actual": actual,
            "matches": not missing and not unexpected,
            "matched": matched,
            "missing": missing,
            "unexpected": unexpected,
        }

    def run_analysis(
        self,
        app: Application,
        label: str,
        paths: list[Path],
        semantic_args: list[str] | None = None,
        expected_diagnostics: Any = None,
    ) -> tuple[dict[str, Any], Any]:
        original_workspace = app.workspace
        if semantic_args is not None:
            app.semantic_args = semantic_args
        invocation = app.invoke_cli(label, self.analyzer_args(paths, app))
        parsed = invocation.get("parsed")
        if not isinstance(parsed, dict):
            app.fail(f"{label}: analyze did not return a JSON object")
            return invocation, None
        diagnostic_gate = self.expected_diagnostic_gate(parsed, expected_diagnostics)
        if diagnostic_gate is not None:
            app.record["checks"][f"{label}_diagnostic_gate"] = diagnostic_gate
        expected_diagnostics_match = (
            isinstance(diagnostic_gate, dict) and diagnostic_gate.get("matches") is True
        )
        if invocation.get("returncode") != 0 and not expected_diagnostics_match:
            app.fail(f"{label}: analyze exited with {invocation.get('returncode')!r}")
        report_path = app.save_report(label, parsed)
        if report_path:
            app.record["checks"][f"{label}_report"] = report_path
        if parsed.get("schema_version") != 1:
            app.fail(f"{label}: report schema_version is not 1")
        compiler_context = app.language == "csharp" or (
            app.language == "typescript" and app.tsconfig is not None
        )
        if (
            compiler_context
            and report_project_complete(parsed) is not True
            and not expected_diagnostics_match
        ):
            app.fail(f"{label}: compiler-backed project report is not complete")
        app.workspace = original_workspace
        return invocation, parsed

    def check_initial_finding(self, app: Application, report: Any, automatic: bool) -> tuple[dict[str, Any] | None, Path | None, dict[str, Any] | None]:
        if report is None:
            return None, None, None
        candidates = find_issues(report, app.rule_key, app.workspace, app.target_path)
        selected: list[tuple[dict[str, Any], dict[str, Any], dict[str, Any]]] = []
        for file_report, issue in candidates:
            fix, error = selected_fix(issue, app.action_id, automatic)
            if error is None and fix is not None:
                selected.append((file_report, issue, fix))

        positive = (
            selected_csharp_positive_case(app.row, app.action_id)
            if app.language == "csharp"
            else None
        )
        multi_control = (
            positive.get("multi_finding_control")
            if isinstance(positive, dict)
            else None
        )
        if not isinstance(multi_control, dict):
            if len(selected) != 1:
                app.fail(
                    f"initial analyze: expected exactly one actionable {app.rule_key} finding, "
                    f"found {len(selected)}"
                )
                return None, None, None
            file_report, issue, fix = selected[0]
            raw_path = file_report.get("path")
            target = app.target_path
            if isinstance(raw_path, str):
                matches = [
                    path
                    for path in app.positive_paths
                    if file_path_matches(raw_path, path, app.workspace)
                ]
                if len(matches) == 1:
                    target = matches[0]
        else:
            expected_count = multi_control.get("expected_finding_count")
            if (
                not isinstance(expected_count, int)
                or isinstance(expected_count, bool)
                or expected_count < 1
            ):
                app.fail("multi_finding_control expected_finding_count must be a positive integer")
                return None, None, None
            if multi_control.get("projection_composition") != "deduplicate-identical-edits-only":
                app.fail(
                    "multi_finding_control must explicitly use "
                    "deduplicate-identical-edits-only projection"
                )
                return None, None, None
            if len(selected) != expected_count:
                app.fail(
                    f"initial analyze: expected {expected_count} actionable {app.rule_key} "
                    f"findings under multi_finding_control, found {len(selected)}"
                )
                return None, None, None
            resolved_targets: list[Path] = []
            for file_report, _, _ in selected:
                raw_path = file_report.get("path")
                target = app.target_path
                if isinstance(raw_path, str):
                    matches = [
                        path
                        for path in app.positive_paths
                        if file_path_matches(raw_path, path, app.workspace)
                    ]
                    if len(matches) != 1:
                        app.fail(
                            "multi_finding_control finding does not resolve to exactly one "
                            f"positive source path: {raw_path!r}"
                        )
                        return None, None, None
                    target = matches[0]
                if target is None:
                    app.fail("multi_finding_control finding has no target source path")
                    return None, None, None
                resolved_targets.append(target)
            if len(set(resolved_targets)) != 1:
                app.fail("multi_finding_control findings span multiple source paths")
                return None, None, None
            try:
                fix = compose_native_fixes(item[2] for item in selected)
            except HarnessError as exc:
                app.fail(f"multi-finding native projection failed: {exc}")
                return None, None, None
            file_report, issue, _ = selected[0]
            raw_path = file_report.get("path")
            target = resolved_targets[0]
            app.record["checks"]["multi_finding"] = {
                "expected_count": expected_count,
                "actual_count": len(selected),
                "findings": [
                    {
                        "rule_key": finding.get("rule_key"),
                        "message": finding.get("message"),
                        "range": finding.get("range"),
                        "file": report_file.get("path"),
                        "action_id": app.action_id,
                        "edits": finding_fix.get("edits"),
                    }
                    for report_file, finding, finding_fix in selected
                ],
                "projection_composition": multi_control.get("projection_composition"),
                "composed_edits": fix.get("edits"),
            }
        app.target_path = target
        app.record["checks"]["finding"] = {
            "rule_key": issue.get("rule_key"),
            "message": issue.get("message"),
            "range": issue.get("range"),
            "file": relpath(target, self.output_root) if target else raw_path,
            "action_id": app.action_id,
            "automatic": automatic,
            "edits": fix.get("edits"),
        }
        reference_action = app.row.get("_reference_action")
        if isinstance(reference_action, dict):
            expected_message = reference_action.get("reference_message")
            actual_message = fix.get("message")
            app.record["checks"]["reference_action"] = {
                "native_action_id": reference_action.get("native_action_id"),
                "reference_message": expected_message,
                "actual_message": actual_message,
                "reference_fix": reference_action.get("reference_fix"),
            }
            reference_fix = reference_action.get("reference_fix")
            if not isinstance(reference_fix, dict) or not reference_fix:
                app.fail("reference action is missing meaningful reference_fix metadata")
        return issue, target, fix

    def qualify_python_negative_controls(self, app: Application) -> None:
        actions = app.row.get("actions")
        selected = [
            action
            for action in actions
            if isinstance(action, dict) and action.get("id") == app.action_id
        ] if isinstance(actions, list) else []
        controls = selected[0].get("negative_controls") if len(selected) == 1 else None
        if not isinstance(controls, list) or not controls:
            app.record["checks"]["negative_controls"] = {
                "status": "none",
                "count": 0,
            }
            return
        original = (
            app.workspace,
            app.semantic_args,
            app.positive_paths,
            app.target_path,
            app.source_before,
        )
        results: list[dict[str, Any]] = []
        try:
            for control_index, control in enumerate(controls):
                if not isinstance(control, dict):
                    app.fail("negative control is not an object")
                    continue
                source = control.get("source")
                expected_ids = control.get("expected_action_ids")
                expected_count = control.get("expected_rule_count")
                if (
                    not isinstance(source, str)
                    or not isinstance(expected_ids, list)
                    or not all(isinstance(value, str) and value for value in expected_ids)
                    or (
                        expected_count is not None
                        and (
                            not isinstance(expected_count, int)
                            or isinstance(expected_count, bool)
                            or expected_count < 0
                        )
                    )
                ):
                    app.fail("negative control metadata is malformed")
                    continue
                name = f"negative-{control_index:03d}"
                control_workspace = app.app_dir / "negative-controls" / name / "workspace"
                target = control_workspace / "src" / "case.py"
                write_text(target, source)
                app.workspace = control_workspace
                app.semantic_args = self.semantic_args_for(app)
                app.positive_paths = [target]
                app.target_path = target
                _, report = self.run_analysis(
                    app,
                    f"{name}-analyze",
                    app.positive_paths,
                )
                candidates = find_issues(report, app.rule_key, app.workspace, app.target_path)
                available_ids = sorted(
                    {
                        alternative.get("id")
                        for _, issue in candidates
                        for alternative in issue.get("alternatives", [])
                        if isinstance(alternative, dict) and isinstance(alternative.get("id"), str)
                    }
                )
                expected_ids_sorted = sorted(set(expected_ids))
                actual_count = len(candidates)
                count_matches = expected_count is None or actual_count == expected_count
                ids_match = available_ids == expected_ids_sorted
                if not count_matches:
                    app.fail(
                        f"negative control {name}: expected {expected_count} {app.rule_key} findings, "
                        f"found {actual_count}"
                    )
                if not ids_match:
                    app.fail(
                        f"negative control {name}: expected action ids {expected_ids_sorted!r}, "
                        f"found {available_ids!r}"
                    )
                results.append({
                    "name": name,
                    "status": "pass" if count_matches and ids_match else "fail",
                    "expected_action_ids": expected_ids_sorted,
                    "actual_action_ids": available_ids,
                    "expected_rule_count": expected_count,
                    "actual_rule_count": actual_count,
                })
        finally:
            (
                app.workspace,
                app.semantic_args,
                app.positive_paths,
                app.target_path,
                app.source_before,
            ) = original
        app.record["checks"]["negative_controls"] = {
            "status": "pass" if results and all(item.get("status") == "pass" for item in results) else "fail",
            "count": len(results),
            "results": results,
        }

    def qualify_python_safety_controls(self, app: Application) -> None:
        actions = app.row.get("actions")
        selected = [
            action
            for action in actions
            if isinstance(action, dict) and action.get("id") == app.action_id
        ] if isinstance(actions, list) else []
        controls = selected[0].get("safety_refusal_controls") if len(selected) == 1 else None
        if not isinstance(controls, list) or not controls:
            app.record["checks"]["safety_refusal_controls"] = {
                "status": "none",
                "count": 0,
            }
            return
        original = (
            app.workspace,
            app.semantic_args,
            app.positive_paths,
            app.target_path,
            app.source_before,
        )
        results: list[dict[str, Any]] = []
        try:
            for control_index, control in enumerate(controls):
                if not isinstance(control, dict):
                    app.fail("safety refusal control is not an object")
                    continue
                source = control.get("source")
                expected_projection = control.get("expected_projection")
                expected_ids = control.get("expected_action_ids")
                expected_increased = control.get("expected_increased")
                if (
                    not isinstance(source, str)
                    or not isinstance(expected_projection, str)
                    or not isinstance(expected_ids, list)
                    or not all(isinstance(value, str) and value for value in expected_ids)
                    or not isinstance(expected_increased, dict)
                    or not all(
                        isinstance(rule, str)
                        and rule
                        and isinstance(count, int)
                        and not isinstance(count, bool)
                        and count >= 1
                        for rule, count in expected_increased.items()
                    )
                ):
                    app.fail("safety refusal control metadata is malformed")
                    continue
                name = str(control.get("name") or f"control-{control_index}")
                control_workspace = app.app_dir / "safety-controls" / f"{control_index:03d}-{name}" / "workspace"
                target = control_workspace / "src" / "case.py"
                write_text(target, source)
                app.workspace = control_workspace
                app.semantic_args = self.semantic_args_for(app)
                app.positive_paths = [target]
                app.target_path = target
                before_hashes = file_hashes(app.positive_paths)
                _, initial_report = self.run_analysis(
                    app,
                    f"safety-{control_index}-initial-analyze",
                    app.positive_paths,
                )
                candidates = find_issues(initial_report, app.rule_key, app.workspace, app.target_path)
                matching = [
                    (file_report, issue, fix)
                    for file_report, issue in candidates
                    for fix, error in [selected_fix(issue, app.action_id, False)]
                    if error is None and fix is not None
                ]
                available_ids = sorted(
                    {
                        alternative.get("id")
                        for _, issue in candidates
                        for alternative in issue.get("alternatives", [])
                        if isinstance(alternative, dict) and isinstance(alternative.get("id"), str)
                    }
                )
                expected_ids_sorted = sorted(set(expected_ids))
                if available_ids != expected_ids_sorted:
                    app.fail(
                        f"safety control {name}: expected action ids {expected_ids_sorted!r}, "
                        f"found {available_ids!r}"
                    )
                if len(matching) != 1:
                    app.fail(
                        f"safety control {name}: expected one actionable {app.action_id!r} finding, "
                        f"found {len(matching)}"
                    )
                    results.append({
                        "name": name,
                        "status": "failed",
                        "expected_action_ids": expected_ids_sorted,
                        "actual_action_ids": available_ids,
                    })
                    continue
                _, issue, fix = matching[0]
                try:
                    projected = apply_native_edits(source, fix.get("edits"))
                except HarnessError as exc:
                    app.fail(f"safety control {name}: native projection failed: {exc}")
                    projected = source
                projection_matches = projected == expected_projection
                if not projection_matches:
                    app.fail(f"safety control {name}: native projection differs from expected projection")
                initial_counts = issue_rule_counts(initial_report)
                projected_report = self.analyze_projected_source(app, target, projected)
                projected_counts = issue_rule_counts(projected_report)
                actual_increased = {
                    rule: count - initial_counts.get(rule, 0)
                    for rule, count in projected_counts.items()
                    if count > initial_counts.get(rule, 0)
                }
                increased_matches = actual_increased == expected_increased
                if not increased_matches:
                    app.fail(
                        f"safety control {name}: expected increased findings {expected_increased!r}, "
                        f"found {actual_increased!r}"
                    )
                dry = app.invoke_cli(
                    f"safety-{control_index}-fix-diff",
                    self.fix_args(app.positive_paths, app, False, apply=False),
                )
                dry_rows = selected_plan_rows(dry.get("parsed"), app.workspace, app.positive_paths)
                dry_selected = plan_has_action(
                    dry.get("parsed"),
                    app.workspace,
                    app.positive_paths,
                    fix.get("edits"),
                )
                if dry.get("returncode") != 0 or not dry_selected:
                    app.fail(f"safety control {name}: fix-diff did not expose the selected action")
                after_dry_hashes = file_hashes(app.positive_paths)
                if after_dry_hashes != before_hashes:
                    app.fail(f"safety control {name}: fix-diff changed source bytes")
                applied = app.invoke_cli(
                    f"safety-{control_index}-fix-apply",
                    self.fix_args(app.positive_paths, app, False, apply=True),
                )
                apply_rows = selected_plan_rows(applied.get("parsed"), app.workspace, app.positive_paths)
                apply_row = apply_rows[0] if len(apply_rows) == 1 else {}
                outcome = {
                    "returncode": applied.get("returncode"),
                    "written": apply_row.get("written"),
                    "applied": apply_row.get("applied"),
                    "verified": apply_row.get("verified"),
                    "unverified": apply_row.get("unverified"),
                    "regressions": apply_row.get("regressions"),
                }
                after_apply_hashes = file_hashes(app.positive_paths)
                rejection_evidence = (
                    isinstance(outcome["unverified"], int)
                    and outcome["unverified"] > 0
                ) or (
                    isinstance(outcome["regressions"], int)
                    and outcome["regressions"] > 0
                )
                refusal = {
                    "returncode_nonzero": applied.get("returncode") != 0,
                    "written_false": outcome["written"] is False,
                    "rejection_evidence": rejection_evidence,
                    "bytes_unchanged": after_apply_hashes == before_hashes,
                }
                refused = all(refusal.values())
                if not refused:
                    app.fail(f"safety control {name}: unsafe apply was not refused")
                results.append({
                    "name": name,
                    "status": "pass" if projection_matches and increased_matches and refused else "fail",
                    "expected_action_ids": expected_ids_sorted,
                    "actual_action_ids": available_ids,
                    "expected_increased": expected_increased,
                    "actual_increased": actual_increased,
                    "projection_matches": projection_matches,
                    "apply": outcome,
                    "refusal": refusal,
                })
        finally:
            (
                app.workspace,
                app.semantic_args,
                app.positive_paths,
                app.target_path,
                app.source_before,
            ) = original
        app.record["checks"]["safety_refusal_controls"] = {
            "status": "pass" if results and all(item.get("status") == "pass" for item in results) else "fail",
            "count": len(results),
            "results": results,
        }

    def record_csharp_negative_compiler_refusal(
        self,
        app: Application,
        invocation: dict[str, Any],
        report: Any,
        paths: list[Path],
        before_hashes: dict[str, str],
    ) -> bool:
        metadata = app.row.get("negative_compiler_refusal")
        if metadata is None:
            return False
        check: dict[str, Any] = {
            "declared": metadata,
            "source_hash_matches": False,
            "invocation": {
                "returncode": invocation.get("returncode"),
                "timed_out": invocation.get("timed_out"),
                "error": invocation.get("error"),
            },
            "actual_compiler_error_ids": [],
            "reference_artifact": None,
            "checks_passed": False,
        }
        valid_metadata = (
            isinstance(metadata, dict)
            and isinstance(metadata.get("source_sha256"), str)
            and re.fullmatch(r"[0-9a-fA-F]{64}", metadata["source_sha256"])
            is not None
            and isinstance(metadata.get("compiler_error_ids"), list)
            and bool(metadata["compiler_error_ids"])
            and all(
                isinstance(value, str) and value
                for value in metadata["compiler_error_ids"]
            )
            and isinstance(metadata.get("reason"), str)
            and bool(metadata["reason"])
            and isinstance(metadata.get("reference_artifact"), str)
            and bool(metadata["reference_artifact"])
        )
        if not valid_metadata:
            app.fail("negative_compiler_refusal metadata is malformed")
            app.record["checks"]["negative_compiler_refusal"] = check
            return False
        expected_source_hash = metadata["source_sha256"]
        check["source_hash_matches"] = expected_source_hash in set(before_hashes.values())
        if not check["source_hash_matches"]:
            app.fail("negative compiler refusal source hash does not match the materialized source")
        warnings = self.compiler_diagnostic_warnings(report)
        actual_error_ids = sorted(
            {
                match
                for warning in warnings
                for match in re.findall(r"\bCS\d+\b", warning.upper())
            }
        )
        check["actual_compiler_error_ids"] = actual_error_ids
        expected_error_ids = metadata["compiler_error_ids"]
        compiler_errors_match = all(
            value.upper() in actual_error_ids for value in expected_error_ids
        )
        check["compiler_errors_match"] = compiler_errors_match
        project_complete = report_project_complete(report)
        check["project_complete"] = project_complete
        check["project_incomplete"] = project_complete is False
        check["exit_code_is_2"] = invocation.get("returncode") == 2
        check["invocation_not_timed_out"] = invocation.get("timed_out") is False
        check["invocation_without_error"] = not invocation.get("error")
        if not compiler_errors_match:
            app.fail("negative compiler refusal lacks the declared compiler-error evidence")
        if project_complete is not False:
            app.fail("negative compiler refusal requires project.complete=false")
        if invocation.get("returncode") != 2:
            app.fail("negative compiler refusal requires analyze exit code 2")
        if invocation.get("timed_out") is not False or invocation.get("error"):
            app.fail("negative compiler refusal cannot use timeout or missing-context evidence")
        artifact_name = metadata["reference_artifact"]
        artifact_path = Path(artifact_name)
        if not artifact_path.is_absolute():
            artifact_path = self.manifest_root / artifact_path
        artifact_payload: Any = None
        try:
            artifact_bytes = artifact_path.read_bytes()
            artifact_payload = json.loads(artifact_bytes.decode("utf-8"))
        except (OSError, UnicodeDecodeError, json.JSONDecodeError):
            artifact_bytes = b""
        artifact_check = {
            "path": str(artifact_path),
            "exists": artifact_path.is_file(),
            "sha256": sha256_bytes(artifact_bytes) if artifact_bytes else None,
            "is_json_object": isinstance(artifact_payload, dict),
        }
        check["reference_artifact"] = artifact_check
        if not artifact_check["exists"] or not artifact_check["is_json_object"]:
            app.fail("negative compiler refusal reference artifact is unavailable or malformed")
        check["checks_passed"] = (
            check["source_hash_matches"]
            and compiler_errors_match
            and check["project_incomplete"]
            and check["exit_code_is_2"]
            and check["invocation_not_timed_out"]
            and check["invocation_without_error"]
            and artifact_check["exists"]
            and artifact_check["is_json_object"]
        )
        app.record["checks"]["negative_compiler_refusal"] = check
        return check["checks_passed"]

    def qualify_negative(self, app: Application, automatic: bool) -> None:
        if app.language == "python":
            self.qualify_python_negative_controls(app)
            self.qualify_python_safety_controls(app)
            return

        original_header = app.csharp_header_format
        if not self.materialize_negative(app):
            app.csharp_header_format = original_header
            return
        negative_workspace = app.app_dir / "negative" / "workspace"
        original_workspace = app.workspace
        original_semantic = app.semantic_args
        app.workspace = negative_workspace
        app.semantic_args = self.semantic_args_for_negative(app)
        app.record["checks"]["negative_semantic_args"] = list(app.semantic_args)
        paths = app.negative_paths
        before = file_hashes(paths)
        before_sources: dict[Path, str] = {}
        for path in paths:
            try:
                before_sources[path] = path.read_bytes().decode("utf-8")
            except (OSError, UnicodeDecodeError) as exc:
                app.fail(f"negative fixture cannot be read as UTF-8: {exc}")
        app.record["checks"]["negative_before_hashes"] = before
        negative = app.row.get("negative")
        declared_gate = negative.get("diagnostic_gate") if isinstance(negative, dict) else None
        expected_diagnostics = (
            declared_gate.get("expected_diagnostics")
            if isinstance(declared_gate, dict)
            else None
        )
        negative_invocation, report = self.run_analysis(
            app,
            "negative-analyze",
            paths,
            app.semantic_args,
            expected_diagnostics=expected_diagnostics,
        )
        if app.language == "csharp" and app.row.get("negative_compiler_refusal") is not None:
            self.record_csharp_negative_compiler_refusal(
                app,
                negative_invocation,
                report,
                paths,
                before,
            )
        observed_gate = app.record["checks"].get("negative-analyze_diagnostic_gate")
        negative_diagnostic_gated = (
            expected_diagnostics is not None
            and isinstance(observed_gate, dict)
            and observed_gate.get("matches") is True
        )
        if expected_diagnostics is not None and not negative_diagnostic_gated:
            app.fail("negative diagnostic gate did not match declared compiler diagnostics")
        app.record["checks"]["negative_diagnostic_gate"] = {
            "declared": declared_gate,
            "observed": observed_gate,
            "status": "diagnostic_gated" if negative_diagnostic_gated else "not_declared",
        }
        negative_compiler_check = app.record["checks"].get("negative_compiler_refusal")
        negative_status = (
            "invalid_input"
            if isinstance(negative_compiler_check, dict)
            and negative_compiler_check.get("checks_passed") is True
            else ("diagnostic_gated" if negative_diagnostic_gated else "safety_refusal")
        )
        app.record["checks"]["negative"] = {
            "status": negative_status,
            "reason": (
                declared_gate.get("reason")
                if isinstance(declared_gate, dict)
                else (negative.get("reason") if isinstance(negative, dict) else None)
            ),
        }
        unsafe: list[dict[str, Any]] = []
        for file_report, issue in find_issues(report, app.rule_key, app.workspace):
            fix, error = selected_fix(issue, app.action_id, automatic)
            if error is None and fix is not None:
                unsafe.append({"path": file_report.get("path"), "range": issue.get("range"), "action_id": app.action_id})
        app.record["checks"]["negative_unsafe_actions"] = unsafe
        if unsafe:
            app.fail("negative fixture exposes the selected unsafe action")
        fix_invocation = app.invoke_cli(
            "negative-fix-diff",
            self.fix_args(paths, app, automatic, apply=False),
        )
        allowed_negative_codes = {0, 1, 2} if negative_diagnostic_gated else {0, 1}
        if fix_invocation.get("returncode") not in allowed_negative_codes:
            app.fail(f"negative-fix-diff: unexpected exit code {fix_invocation.get('returncode')!r}")
        plan = fix_invocation.get("parsed")
        plan_selected = plan_has_action(plan, app.workspace, paths, None)
        app.record["checks"]["negative_plan_has_selected_action"] = plan_selected
        if plan_selected:
            app.fail("negative fixture planned the selected action")
        after_dry = file_hashes(paths)
        app.record["checks"]["negative_after_dry_run_hashes"] = after_dry
        if before != after_dry:
            app.fail("negative fixture bytes changed during dry-run")
        before_sources = {path: mechanical_fixed(source) for path, source in before_sources.items()}
        apply_invocation = app.invoke_cli(
            "negative-fix-apply",
            self.fix_args(paths, app, automatic, apply=True),
        )
        if apply_invocation.get("returncode") not in allowed_negative_codes:
            app.fail(f"negative-fix-apply: unexpected exit code {apply_invocation.get('returncode')!r}")
        apply_plan = apply_invocation.get("parsed")
        apply_selected = plan_has_action(apply_plan, app.workspace, paths, None)
        app.record["checks"]["negative_apply_has_selected_action"] = apply_selected
        if apply_selected:
            app.fail("negative fixture apply planned the selected action")
        expected_hashes = {
            str(path): sha256_bytes(source.encode("utf-8"))
            for path, source in before_sources.items()
        }
        after_apply = file_hashes(paths)
        if app.row.get("negative_compiler_refusal") is not None and after_apply != before:
            app.fail("negative compiler refusal changed source bytes")
        app.record["checks"]["negative_after_apply_hashes"] = after_apply
        app.record["checks"]["negative_expected_apply_hashes"] = expected_hashes
        if after_apply != expected_hashes:
            app.fail("negative fixture apply changed bytes beyond the CLI final-newline repair")
        app.workspace = original_workspace
        app.semantic_args = original_semantic
        app.csharp_header_format = original_header
    def enforce_declared_reanalysis(self, app: Application) -> None:
        if app.language == "python":
            actions = app.row.get("actions")
            if not isinstance(actions, list):
                return
            selected = [
                action
                for action in actions
                if isinstance(action, dict) and action.get("id") == app.action_id
            ]
        elif app.language in {"javascript", "typescript"}:
            reference_action = app.row.get("_reference_action")
            selected = [reference_action] if isinstance(reference_action, dict) else []
        elif app.language == "csharp":
            positive = selected_csharp_positive_case(app.row, app.action_id)
            selected = [positive] if isinstance(positive, dict) else []
        else:
            return
        if len(selected) != 1:
            return
        reanalysis = selected[0].get("reanalysis")
        if reanalysis is None:
            return
        app.record["checks"]["reanalysis"] = reanalysis
        if not isinstance(reanalysis, dict):
            app.fail("manifest reanalysis metadata is not an object")
            return
        if reanalysis.get("status") != "REANALYSIS_GATE_REJECTED":
            if app.language == "csharp":
                app.fail("CSharp reanalysis metadata must declare REANALYSIS_GATE_REJECTED")
            return
        increased = reanalysis.get("increased")
        valid_increased = (
            isinstance(increased, dict)
            and bool(increased)
            and all(
                isinstance(rule, str)
                and bool(rule)
                and isinstance(count, int)
                and not isinstance(count, bool)
                and count >= 1
                for rule, count in increased.items()
            )
        )
        expected_target_reduced = app.language in {
            "javascript",
            "typescript",
            "csharp",
        }
        reason = reanalysis.get("reason")
        expectation_only = reanalysis.get("expectation_only")
        if (
            reanalysis.get("target_reduced") is not expected_target_reduced
            or not valid_increased
            or not isinstance(reason, str)
            or not reason
            or (
                app.language == "csharp"
                and expectation_only is not True
            )
        ):
            app.fail(
                "manifest reanalysis gate rejection has invalid target reduction, "
                "increased findings, reason, or expectation_only metadata"
            )
        if app.language == "csharp":
            derived_overlay = reanalysis.get("derived_overlay")
            projected = (
                derived_overlay.get("projected_reanalysis")
                if isinstance(derived_overlay, dict)
                else None
            )
            if (
                not isinstance(derived_overlay, dict)
                or not isinstance(derived_overlay.get("proof_paths"), dict)
                or not isinstance(projected, dict)
            ):
                app.fail(
                    "CSharp reanalysis metadata must retain derived projected proof"
                )
            elif (
                projected.get("action_id") not in {None, app.action_id}
                or projected.get("rule_key") not in {None, app.rule_key}
            ):
                app.fail(
                    "CSharp reanalysis projected proof is not keyed to the selected action"
                )

    def analyze_projected_source(self, app: Application, target: Path, projected: str) -> Any:
        original_workspace = app.workspace
        original_project_path = app.project_path
        original_nuget_config = app.nuget_config
        original_tsconfig = app.tsconfig
        original_semantic_args = list(app.semantic_args)
        # Keep the probe outside the original SDK project: its implicit Compile
        # glob must not consume projected sources or generated artifacts.
        projected_workspace = app.app_dir / "reanalysis-projected"
        projected_paths: list[Path] = []
        try:
            for path in app.positive_paths:
                relative = path.relative_to(original_workspace)
                projected_path = projected_workspace / relative
                content = projected.encode("utf-8") if path == target else path.read_bytes()
                write_bytes(projected_path, content)
                projected_paths.append(projected_path)
            if app.language == "csharp":
                if original_project_path is not None:
                    project_relative = original_project_path.relative_to(original_workspace)
                    projected_project = projected_workspace / project_relative
                    write_bytes(projected_project, original_project_path.read_bytes())
                if original_nuget_config is not None:
                    nuget_relative = original_nuget_config.relative_to(original_workspace)
                    projected_nuget = projected_workspace / nuget_relative
                    write_bytes(projected_nuget, original_nuget_config.read_bytes())
            elif app.language == "typescript":
                if original_tsconfig is not None:
                    tsconfig_relative = original_tsconfig.relative_to(original_workspace)
                    projected_tsconfig = projected_workspace / tsconfig_relative
                    write_bytes(projected_tsconfig, original_tsconfig.read_bytes())
                    base_tsconfig = original_tsconfig.parent / "tsconfig.base.json"
                    if base_tsconfig.is_file():
                        base_relative = base_tsconfig.relative_to(original_workspace)
                        projected_base_tsconfig = projected_workspace / base_relative
                        write_bytes(projected_base_tsconfig, base_tsconfig.read_bytes())
        except (OSError, ValueError) as exc:
            app.fail(f"cannot materialize projected reanalysis source: {exc}")
            return None
        app.record["checks"]["reanalysis_projected_sources"] = file_hashes(projected_paths)
        try:
            app.workspace = projected_workspace
            if app.language == "csharp":
                if original_project_path is not None:
                    app.project_path = projected_workspace / original_project_path.relative_to(
                        original_workspace
                    )
                if original_nuget_config is not None:
                    app.nuget_config = projected_workspace / original_nuget_config.relative_to(
                        original_workspace
                    )
            elif app.language == "typescript" and original_tsconfig is not None:
                app.tsconfig = projected_workspace / original_tsconfig.relative_to(
                    original_workspace
                )
            app.semantic_args = self.semantic_args_for(app)
            _, report = self.run_analysis(app, "reanalysis-projected-analyze", projected_paths)
            return report
        finally:
            app.workspace = original_workspace
            app.project_path = original_project_path
            app.nuget_config = original_nuget_config
            app.tsconfig = original_tsconfig
            app.semantic_args = original_semantic_args

    @staticmethod
    def projection_classification(actual: str, expected: str) -> str:
        if actual == expected:
            return "exact-text"
        actual_without_whitespace = "".join(
            character for character in actual if not character.isspace()
        )
        expected_without_whitespace = "".join(
            character for character in expected if not character.isspace()
        )
        if actual_without_whitespace == expected_without_whitespace:
            return "whitespace-only"
        return "token/content-difference"

    def validate_reanalysis_candidate(
        self,
        app: Application,
        initial_report: Any,
        projected_report: Any,
        declared: dict[str, Any],
        projected_source: str,
        expected_source: str,
    ) -> bool | None:
        validation: dict[str, Any] = {
            "declared": declared,
            "projected_report_available": isinstance(projected_report, dict),
            "projected_report_schema_version": (
                projected_report.get("schema_version")
                if isinstance(projected_report, dict)
                else None
            ),
        }
        if (
            not isinstance(initial_report, dict)
            or initial_report.get("schema_version") != SCHEMA_VERSION
            or report_project_complete(initial_report) is not True
            or not isinstance(projected_report, dict)
            or projected_report.get("schema_version") != SCHEMA_VERSION
            or report_project_complete(projected_report) is not True
        ):
            validation.update(
                {
                    "status": "invalid_project_report",
                    "matches_declared": False,
                    "unresolved": True,
                }
            )
            app.record["checks"]["reanalysis_validation"] = validation
            app.fail("projected reanalysis did not produce a complete schema-v1 report")
            return
        before_counts = issue_rule_counts(initial_report)
        after_counts = issue_rule_counts(projected_report)
        target_before = before_counts.get(app.rule_key, 0)
        target_after = after_counts.get(app.rule_key, 0)
        increased = {
            rule: count - before_counts.get(rule, 0)
            for rule, count in after_counts.items()
            if count > before_counts.get(rule, 0)
        }
        observed_target_reduced = target_after < target_before
        observed_reanalysis_rejected = (
            not observed_target_reduced or bool(increased)
        )
        declared_increased = declared.get("increased")
        matches_declared = (
            observed_target_reduced is declared.get("target_reduced")
            and increased == declared_increased
        )
        validation.update(
            {
                "status": (
                    "REANALYSIS_GATE_REJECTED"
                    if observed_reanalysis_rejected
                    else "REANALYSIS_ACCEPTED"
                ),
                "target_before": target_before,
                "target_after": target_after,
                "target_reduced": observed_target_reduced,
                "increased": increased,
                "matches_declared": matches_declared,
                "historical_matches": matches_declared,
                "fresh_candidate_safe": not observed_reanalysis_rejected,
                "unresolved": True,
                "projected_source_sha256": sha256_bytes(
                    projected_source.encode("utf-8")
                ),
                "expected_source_sha256": sha256_bytes(
                    expected_source.encode("utf-8")
                ),
            }
        )
        if app.language == "csharp":
            derived_overlay = declared.get("derived_overlay")
            historical = (
                derived_overlay.get("projected_reanalysis")
                if isinstance(derived_overlay, dict)
                else None
            )
            historical_projection = (
                historical.get("projection")
                if isinstance(historical, dict)
                else None
            )
            current_classification = self.projection_classification(
                projected_source, expected_source
            )
            projection_evidence: dict[str, Any] = {
                "classification": current_classification,
                "actual": projected_source,
                "actual_sha256": sha256_bytes(projected_source.encode("utf-8")),
                "expected": expected_source,
                "expected_sha256": sha256_bytes(expected_source.encode("utf-8")),
            }
            validation["projection"] = projection_evidence
            historical_valid = (
                isinstance(historical_projection, dict)
                and isinstance(historical_projection.get("actual"), str)
                and isinstance(historical_projection.get("expected"), str)
                and isinstance(historical_projection.get("classification"), str)
                and historical_projection.get("actual_sha256")
                == sha256_bytes(
                    historical_projection["actual"].encode("utf-8")
                )
                and historical_projection.get("expected_sha256")
                == sha256_bytes(
                    historical_projection["expected"].encode("utf-8")
                )
                and historical_projection.get("expected") == expected_source
                and historical_projection.get("classification")
                == self.projection_classification(
                    historical_projection["actual"],
                    historical_projection["expected"],
                )
            )
            projection_evidence["historical"] = {
                "classification": (
                    historical_projection.get("classification")
                    if isinstance(historical_projection, dict)
                    else None
                ),
                "actual": (
                    historical_projection.get("actual")
                    if isinstance(historical_projection, dict)
                    else None
                ),
                "actual_sha256": (
                    historical_projection.get("actual_sha256")
                    if isinstance(historical_projection, dict)
                    else None
                ),
                "expected": (
                    historical_projection.get("expected")
                    if isinstance(historical_projection, dict)
                    else None
                ),
                "expected_sha256": (
                    historical_projection.get("expected_sha256")
                    if isinstance(historical_projection, dict)
                    else None
                ),
                "valid": historical_valid,
            }
            if not historical_valid:
                matches_declared = False
                app.fail(
                    "CSharp reanalysis projection evidence is stale or malformed"
                )
            projection_evidence["reference_different"] = (
                current_classification == "token/content-difference"
            )
        validation["matches_declared"] = matches_declared
        if observed_reanalysis_rejected:
            validation["unresolved"] = False
            app.record["checks"]["reanalysis_validation"] = validation
            return True
        validation["status"] = "REANALYSIS_ACCEPTED"
        validation["unresolved"] = False
        app.record["checks"]["reanalysis_validation"] = validation
        return False

    def record_csharp_reference_controls(self, app: Application) -> None:
        controls = app.row.get("reference_no_action_controls")
        if controls is None:
            return
        if not isinstance(controls, list) or not controls:
            app.fail("reference_no_action_controls must be a nonempty list")
            return
        original = (
            app.workspace,
            app.project_path,
            app.nuget_config,
            app.semantic_args,
            app.positive_paths,
            app.target_path,
            app.source_before,
            app.csharp_header_format,
        )
        results: list[dict[str, Any]] = []
        try:
            for index, control in enumerate(controls):
                if not isinstance(control, dict):
                    app.fail(f"reference no-action control {index} is not an object")
                    continue
                files = control.get("project_files")
                if not isinstance(files, list) or not files:
                    app.fail(f"reference no-action control {index} has no project_files")
                    continue
                source_hashes: dict[str, str] = {}
                malformed = False
                for item in files:
                    if (
                        not isinstance(item, dict)
                        or not isinstance(item.get("path"), str)
                        or not isinstance(item.get("source"), str)
                    ):
                        malformed = True
                        break
                    source_hashes[item["path"]] = sha256_bytes(item["source"].encode("utf-8"))
                if malformed:
                    app.fail(f"reference no-action control {index} has malformed source provenance")
                    continue
                declared_hash = control.get("source_sha256")
                observed_hash = next(iter(source_hashes.values()), "")
                if observed_hash != declared_hash:
                    app.fail(f"reference no-action control {index} source hash mismatch")
                artifact = control.get("reference_artifact")
                artifact_path = (
                    self.manifest_root / artifact
                    if isinstance(artifact, str) and not Path(artifact).is_absolute()
                    else None
                )
                reference_evidence = reference_no_action_evidence(
                    artifact_path,
                    control.get("reference_artifact_sha256"),
                    control.get("reference_selector"),
                    str(app.row.get("rule") or app.rule_key.split(":", 1)[-1]),
                    str(control.get("action_id") or ""),
                    source_hashes,
                )
                for error in reference_evidence.get("errors", []):
                    app.fail(
                        f"reference no-action control {index} provenance: {error}"
                    )
                control_dir = app.app_dir / "reference-no-action-controls" / f"{index:03d}"
                control_workspace = control_dir / "workspace"
                control_workspace.mkdir(parents=True, exist_ok=True)
                app.workspace = control_workspace
                paths = self.materialize_csharp_files(app, files, f"reference control {index}")
                app.positive_paths = paths
                app.target_path = paths[0] if paths else None
                context = control.get("project_context")
                if not isinstance(context, dict):
                    positive = selected_csharp_positive_case(app.row, app.action_id)
                    context = positive.get("project_context") if isinstance(positive, dict) else None
                self.prepare_csharp(app, paths, context)
                app.semantic_args = self.semantic_args_for(app)
                app.source_before = file_hashes(paths)
                _, report = self.run_analysis(
                    app,
                    f"reference-no-action-{index:03d}-analyze",
                    paths,
                    expected_diagnostics=control.get("expected_diagnostics"),
                )
                findings = find_issues(report, app.rule_key, app.workspace, app.target_path)
                expected_targets = control.get("expected_target_count", 0)
                expected_actions = control.get("expected_action_count", 0)
                if reference_evidence.get("fixture_kind") != "positive":
                    app.fail(
                        f"reference no-action control {index} did not resolve a positive frozen fixture"
                    )
                if reference_evidence.get("target_diagnostic_count") != expected_targets:
                    app.fail(
                        f"reference no-action control {index} target expectation is not "
                        "grounded in the selected provider fixture"
                    )
                if reference_evidence.get("offered_action_count") != expected_actions:
                    app.fail(
                        f"reference no-action control {index} action expectation is not "
                        "grounded in the selected provider fixture"
                    )
                expected_status = control.get("expected_upstream_status")
                if (
                    expected_status is not None
                    and reference_evidence.get("availability") != expected_status
                ):
                    app.fail(
                        f"reference no-action control {index} upstream availability does not "
                        "match the selected provider fixture"
                    )
                selected_action_findings = [
                    (file_report, issue)
                    for file_report, issue in findings
                    if any(
                        isinstance(alternative, dict)
                        and alternative.get("id") == control.get("action_id")
                        for alternative in issue.get("alternatives", [])
                    )
                ]
                dry = app.invoke_cli(
                    f"reference-no-action-{index:03d}-fix-diff",
                    self.fix_args(paths, app, automatic=False, apply=False),
                )
                dry_parsed = dry.get("parsed")
                planned_action = plan_has_declared_action(
                    dry_parsed,
                    app.workspace,
                    paths,
                    app.rule_key,
                    str(control.get("action_id") or ""),
                )
                dry_hashes = file_hashes(paths)
                if dry_hashes != app.source_before:
                    app.fail(
                        f"reference no-action control {index} fix-diff modified immutable input bytes"
                    )
                expected_fix_exits = control.get("expected_fix_diff_exit_codes")
                if expected_fix_exits is None:
                    expected_fix_exit = control.get("expected_fix_diff_exit_code")
                    expected_fix_exits = [expected_fix_exit]
                if (
                    not isinstance(expected_fix_exits, list)
                    or not expected_fix_exits
                    or any(
                        not isinstance(value, int) or isinstance(value, bool)
                        for value in expected_fix_exits
                    )
                ):
                    app.fail(
                        f"reference no-action control {index} has no valid expected fix-diff exit codes"
                    )
                    expected_fix_exits = []
                elif dry.get("returncode") not in expected_fix_exits:
                    app.fail(
                        f"reference no-action control {index} expected fix-diff exit in "
                        f"{expected_fix_exits!r}, got {dry.get('returncode')!r}"
                    )
                applied = app.invoke_cli(
                    f"reference-no-action-{index:03d}-fix-apply",
                    self.fix_args(paths, app, automatic=False, apply=True),
                )
                applied_parsed = applied.get("parsed")
                applied_rows = (
                    applied_parsed.get("files")
                    if isinstance(applied_parsed, dict)
                    else []
                )
                if not isinstance(applied_rows, list):
                    applied_rows = []
                applied_planned = plan_has_declared_action(
                    applied_parsed,
                    app.workspace,
                    paths,
                    app.rule_key,
                    str(control.get("action_id") or ""),
                )
                applied_selected_alternative = any(
                    item.get("id") == control.get("action_id")
                    and item.get("rule_key") == app.rule_key
                    for item in plan_alternatives(
                        applied_parsed,
                        app.workspace,
                        paths,
                    )
                    if isinstance(item, dict)
                )
                applied_count = (
                    applied_parsed.get("applied")
                    if isinstance(applied_parsed, dict)
                    else None
                )
                applied_written = any(
                    isinstance(item, dict) and item.get("written") is True
                    for item in applied_rows
                )
                applied_file_counts = {
                    key: sum(
                        int(item.get(key, 0))
                        for item in applied_rows
                        if isinstance(item, dict)
                        and isinstance(item.get(key), int)
                        and not isinstance(item.get(key), bool)
                    )
                    for key in ("applied", "verified", "unverified", "regressions")
                }
                if expected_fix_exits and applied.get("returncode") not in expected_fix_exits:
                    app.fail(
                        f"reference no-action control {index} expected fix-apply exit in "
                        f"{expected_fix_exits!r}, got {applied.get('returncode')!r}"
                    )
                if (
                    applied_count != 0
                    or applied_planned
                    or applied_selected_alternative
                    or applied_written
                ):
                    app.fail(
                        f"reference no-action control {index} fix-apply exposed or wrote "
                        "the selected action"
                    )
                if any(
                    applied_file_counts[key] != 0
                    for key in ("applied", "verified", "regressions")
                ):
                    app.fail(
                        f"reference no-action control {index} fix-apply reported a mutation"
                    )
                after_hashes = file_hashes(paths)
                if after_hashes != app.source_before:
                    app.fail(
                        f"reference no-action control {index} fix-apply modified immutable input bytes"
                    )
                control_status = (
                    "pass"
                    if (
                        not reference_evidence.get("errors")
                        and reference_evidence.get("artifact_sha256_matches") is True
                        and reference_evidence.get("selector_valid") is True
                        and reference_evidence.get("selector_contains_source") is True
                        and reference_evidence.get("fixture_source_hash_matches") is True
                        and reference_evidence.get("fixture_kind") == "positive"
                        and reference_evidence.get("target_diagnostic_count") == expected_targets
                        and reference_evidence.get("offered_action_count") == expected_actions
                        and reference_evidence.get("availability")
                        == control.get("expected_upstream_status")
                        and len(findings) == expected_targets
                        and len(selected_action_findings) == expected_actions
                        and not planned_action
                        and dry.get("returncode") in expected_fix_exits
                        and dry_hashes == app.source_before
                        and applied.get("returncode") in expected_fix_exits
                        and applied_count == 0
                        and not applied_planned
                        and not applied_selected_alternative
                        and not applied_written
                        and all(
                            applied_file_counts[key] == 0
                            for key in ("applied", "verified", "regressions")
                        )
                        and after_hashes == app.source_before
                    )
                    else "fail"
                )
                result = {
                    "status": control_status,
                    "name": control.get("name"),
                    "action_id": control.get("action_id"),
                    "expected_upstream_status": control.get("expected_upstream_status"),
                    "reference_artifact": artifact,
                    "reference_artifact_sha256": control.get("reference_artifact_sha256"),
                    "reference_selector": control.get("reference_selector"),
                    "reference_evidence": reference_evidence,
                    "source_hashes": source_hashes,
                    "declared_source_sha256": declared_hash,
                    "source_hash_matches": observed_hash == declared_hash,
                    "reference_artifact_present": reference_evidence.get("artifact_present"),
                    "analysis_target_count": len(findings),
                    "expected_target_count": expected_targets,
                    "actionable_finding_count": len(selected_action_findings),
                    "expected_action_count": expected_actions,
                    "fix_diff_exit_code": dry.get("returncode"),
                    "expected_fix_diff_exit_codes": expected_fix_exits,
                    "selected_action_planned": planned_action,
                    "dry_bytes_unchanged": dry_hashes == app.source_before,
                    "fix_apply_exit_code": applied.get("returncode"),
                    "fix_apply": {
                        "applied": applied_count,
                        "selected_action_planned": applied_planned,
                        "selected_action_alternative": applied_selected_alternative,
                        "written": applied_written,
                        "file_counts": applied_file_counts,
                    },
                    "bytes_unchanged": after_hashes == app.source_before,
                    "native_divergence": control.get("native_divergence"),
                }
                results.append(result)
        finally:
            (
                app.workspace,
                app.project_path,
                app.nuget_config,
                app.semantic_args,
                app.positive_paths,
                app.target_path,
                app.source_before,
                app.csharp_header_format,
            ) = original
        app.record["checks"]["reference_no_action_controls"] = {
            "status": "pass"
            if len(results) == len(controls)
            and all(item.get("status") == "pass" for item in results)
            else "fail",
            "native_execution": "analyze-fix-diff-and-apply",
            "count": len(results),
            "results": results,
        }

