            ),
            "native_execution": "analyze-only-compiler-refusal",
            "count": len(results),
            "results": results,
        }

    def qualify_action(self, app: Application, automatic: bool) -> None:
        self.enforce_declared_reanalysis(app)
        declared_reanalysis = app.record["checks"].get("reanalysis")
        reanalysis_gate_rejected = (
            isinstance(declared_reanalysis, dict)
            and declared_reanalysis.get("status") == "REANALYSIS_GATE_REJECTED"
        )
        reanalysis_declared = reanalysis_gate_rejected
        multi_control: dict[str, Any] | None = None
        if app.language == "python":
            if not self.materialize_python(app):
                return
        elif app.language in {"javascript", "typescript"}:
            if not self.materialize_jsts(app):
                return
        elif app.language == "csharp":
            self.record_csharp_reference_controls(app)
            self.record_csharp_compiler_refusal_controls(app)
            positive = selected_csharp_positive_case(app.row, app.action_id)
            if positive is None:
                app.fail("manifest has no unique positive case for action")
                return

            declared_multi_control = positive.get("multi_finding_control")
            if isinstance(declared_multi_control, dict):
                multi_control = declared_multi_control
                app.record["checks"]["multi_finding_control"] = multi_control
            diagnostic_gate = positive.get("diagnostic_gate")
            if isinstance(diagnostic_gate, dict):
                app.record["checks"]["expected_source"] = positive.get("expected_source")
                app.record["checks"]["positive_case"] = positive
                if not self.materialize_csharp(app, positive):
                    return
                if app.unavailable:
                    return
                app.semantic_args = self.semantic_args_for(app)
                app.record["checks"]["semantic_args"] = list(app.semantic_args)
                expected_diagnostics = diagnostic_gate.get("expected_diagnostics")
                _, initial_report = self.run_analysis(
                    app,
                    "initial-analyze",
                    app.positive_paths,
                    expected_diagnostics=expected_diagnostics,
                )
                observed_gate = app.record["checks"].get("initial-analyze_diagnostic_gate")
                app.record["checks"]["diagnostic_gate"] = {
                    "declared": diagnostic_gate,
                    "observed": observed_gate,
                }
                if not isinstance(observed_gate, dict) or observed_gate.get("matches") is not True:
                    app.fail("diagnostic-gated positive fixture did not match declared compiler diagnostics")
                else:
                    app.mark_unavailable(
                        str(
                            diagnostic_gate.get("reason")
                            or positive.get("semantic_result")
                            or "manifest marks action as diagnostic-gated"
                        )
                    )
                return
            if positive.get("executable") is not True or positive.get("expected_source") is None:
                app.mark_unavailable(str(positive.get("semantic_result") or "manifest marks action as unavailable"))
                self.materialize_csharp(app, positive)
                app.record["checks"]["expected_source"] = positive.get("expected_source")
                app.record["checks"]["positive_case"] = positive
                return
            app.record["checks"]["expected_source"] = positive.get("expected_source")
            if not self.materialize_csharp(app, positive):
                return
        else:
            app.fail(f"unsupported application language {app.language!r}")
            return
        if app.unavailable:
            return
        app.semantic_args = self.semantic_args_for(app)
        app.record["checks"]["semantic_args"] = list(app.semantic_args)
        _, initial_report = self.run_analysis(app, "initial-analyze", app.positive_paths)
        issue, target, fix = self.check_initial_finding(app, initial_report, automatic)
        if issue is None or target is None or fix is None:
            self.qualify_negative(app, automatic)
            return
        try:
            source = target.read_text(encoding="utf-8", newline="")
        except TypeError:
            source = target.read_bytes().decode("utf-8")
        except OSError as exc:
            app.fail(f"cannot read initial target source: {exc}")
            return
        try:
            projected = apply_native_edits(source, fix.get("edits"))
        except HarnessError as exc:
            app.fail(f"native projection failed: {exc}")
            projected = source
        expected: Any
        if app.language == "csharp":
            positives = app.row.get("positive_cases")
            selected_positive = next((item for item in positives if isinstance(item, dict) and item.get("action_id") == app.action_id), {}) if isinstance(positives, list) else {}
            expected = selected_positive.get("expected_source")
        elif app.language == "python":
            expected = next((item.get("expected_projection") for item in app.row.get("actions", []) if isinstance(item, dict) and item.get("id") == app.action_id), None)
        else:
            expected = app.row.get("expected")
        expected_is_concrete = (
            concrete_expected(expected, source) if app.language == "python" else isinstance(expected, str)
        )
        app.record["checks"]["projection"] = {
            "expected": expected,
            "actual": projected,
            "expected_concrete": expected_is_concrete,
            "matches_declared": projected == expected,
            "initial_sha256": sha256_bytes(source.encode("utf-8")),
            "projected_sha256": sha256_bytes(projected.encode("utf-8")),
        }
        projection_mismatch_is_declared = False
        if not expected_is_concrete:
            app.fail("manifest expected projection is prose or otherwise unusable")
        elif projected != expected:
            projection_mismatch_is_declared = False
            if reanalysis_gate_rejected and app.language == "csharp":
                derived_overlay = declared_reanalysis.get("derived_overlay")
                historical = (
                    derived_overlay.get("projected_reanalysis")
                    if isinstance(derived_overlay, dict)
                    else None
                )
                historical_projection = (
                    historical.get("projection")
                    if isinstance(historical, dict)
                    else None
                )
                projection_mismatch_is_declared = (
                    isinstance(historical_projection, dict)
                    and isinstance(historical_projection.get("classification"), str)
                    and self.projection_classification(projected, expected)
                    == historical_projection.get("classification")
                )
            correction = app.row.get("_native_action_correction")
            if (
                app.row.get("_native_reference_projection_mismatch") is True
                and isinstance(correction, dict)
                and isinstance(correction.get("native_mapping_mismatch"), str)
                and correction.get("native_mapping_mismatch")
                and correction.get("source_sha256")
                == sha256_bytes(source.encode("utf-8"))
                and correction.get("expected_source") == expected
            ):
                projection_mismatch_is_declared = True
                app.record["checks"]["projection"]["status"] = "reference_different"
            app.record["checks"]["projection"]["classification"] = (
                self.projection_classification(projected, expected)
                if isinstance(expected, str)
                else None
            )
            app.record["checks"]["projection"]["classification_declared"] = (
                projection_mismatch_is_declared
            )
            if (
                not projection_mismatch_is_declared
                and not reanalysis_declared
            ):
                app.fail("native finding edits do not produce the manifest expected projection")
        if projected == source:
            app.fail("native finding edits project to unchanged source")
        dry = app.invoke_cli("fix-diff", self.fix_args(app.positive_paths, app, automatic, apply=False))
        dry_parsed = dry.get("parsed")
        dry_has_selected_plan = plan_has_action(
            dry_parsed,
            app.workspace,
            app.positive_paths,
            fix.get("edits"),
        )
        dry_check = {
            "exit_code": dry.get("returncode"),
            "has_selected_plan": dry_has_selected_plan,
            "alternative_ids": [
                item.get("alternative", {}).get("id")
                for item in plan_alternatives(
                    dry_parsed,
                    app.workspace,
                    app.positive_paths,
                )
                if isinstance(item.get("alternative"), dict)
            ],
        }
        if isinstance(multi_control, dict):
            cli = multi_control.get("cli")
            if not isinstance(cli, dict):
                app.fail("multi_finding_control is missing its cli expectations")
                cli = {}
            planned_fix_count = len(
                plan_fix_entries(dry_parsed, app.workspace, app.positive_paths)
            )
            dry_skipped = dry_parsed.get("skipped") if isinstance(dry_parsed, dict) else None
            dry_check.update(
                {
                    "planned_fix_count": planned_fix_count,
                    "skipped": dry_skipped,
                    "expected_exit_code": cli.get("dry_run_exit_code"),
                    "expected_planned_fix_count": cli.get("dry_run_planned_fix_count"),
                    "expected_skipped": cli.get("dry_run_skipped"),
                }
            )
            expected_values = (
                cli.get("dry_run_exit_code"),
                cli.get("dry_run_planned_fix_count"),
                cli.get("dry_run_skipped"),
            )
            if not all(
                isinstance(value, int) and not isinstance(value, bool)
                for value in expected_values
            ):
                app.fail("multi_finding_control dry-run expectations must be integers")
            if dry.get("returncode") != cli.get("dry_run_exit_code"):
                app.fail(
                    "fix-diff: multi-finding control expected exit code "
                    f"{cli.get('dry_run_exit_code')!r}, got {dry.get('returncode')!r}"
                )
            if planned_fix_count != cli.get("dry_run_planned_fix_count"):
                app.fail(
                    "fix-diff: multi-finding control expected "
                    f"{cli.get('dry_run_planned_fix_count')!r} planned fixes, "
                    f"got {planned_fix_count!r}"
                )
            if dry_skipped != cli.get("dry_run_skipped"):
                app.fail(
                    "fix-diff: multi-finding control expected "
                    f"{cli.get('dry_run_skipped')!r} skipped fixes, got {dry_skipped!r}"
                )
        else:
            if dry.get("returncode") != 0:
                app.fail(f"fix-diff: expected exit code 0, got {dry.get('returncode')!r}")
        app.record["checks"]["dry_run"] = dry_check
        if not dry_has_selected_plan:
            app.fail("fix-diff: selected action is missing from the dry-run plan")
        dry_hashes = file_hashes(app.positive_paths)
        app.record["checks"]["dry_run"]["after_hashes"] = dry_hashes
        if dry_hashes != app.source_before:
            app.fail("fix-diff modified immutable input bytes")
        projected_reanalysis = (
            self.analyze_projected_source(app, target, projected)
            if reanalysis_declared
            else None
        )
        if reanalysis_declared:
            if isinstance(expected, str):
                fresh_decision = self.validate_reanalysis_candidate(
                    app,
                    initial_report,
                    projected_reanalysis,
                    declared_reanalysis,
                    projected,
                    expected,
                )
                if fresh_decision is not None:
                    reanalysis_gate_rejected = fresh_decision
                if (
                    app.language == "csharp"
                    and projected != expected
                    and not projection_mismatch_is_declared
                ):
                    app.fail(
                        "CSharp reanalysis projection mismatch lacks historical provenance"
                    )
                if (
                    app.language == "csharp"
                    and projected != expected
                    and fresh_decision is False
                ):
                    app.fail(
                        "accepted CSharp reanalysis candidate differs from expected projection"
                    )
            else:
                app.fail("reanalysis gate requires a concrete expected source")
        if automatic:
            selected_ids = []
        else:
            selected_ids = [item.get("id") for item in issue.get("alternatives", []) if isinstance(item, dict)]
            if app.action_id not in selected_ids:
                app.fail("initial finding alternatives do not contain the selected action id")
        applied = app.invoke_cli("fix-apply", self.fix_args(app.positive_paths, app, automatic, apply=True))
        applied_parsed = applied.get("parsed")
        apply_rows = selected_plan_rows(applied_parsed, app.workspace, app.positive_paths)
        apply_row = apply_rows[0] if len(apply_rows) == 1 else {}
        outcome = {
            "exit_code": applied.get("returncode"),
            "written": apply_row.get("written"),
            "applied": apply_row.get("applied"),
            "verified": apply_row.get("verified"),
            "unverified": apply_row.get("unverified"),
            "regressions": apply_row.get("regressions"),
            "skipped": apply_row.get("skipped"),
        }
        app.record["checks"]["apply"] = outcome
        if reanalysis_gate_rejected:
            rejection_evidence = (
                (isinstance(outcome["unverified"], int)
                and not isinstance(outcome["unverified"], bool)
                and outcome["unverified"] > 0)
                or (isinstance(outcome["regressions"], int)
                and not isinstance(outcome["regressions"], bool)
                and outcome["regressions"] > 0)
            )
            validation = app.record["checks"].get("reanalysis_validation")
            refusal = {
                "expected_refusal": True,
                "returncode_nonzero": (
                    isinstance(applied.get("returncode"), int)
                    and applied.get("returncode") != 0
                ),
                "invocation_not_timed_out": applied.get("timed_out") is False,
                "invocation_without_error": not applied.get("error"),
                "written_false": outcome["written"] is False,
                "applied_zero": (
                    isinstance(outcome["applied"], int)
                    and not isinstance(outcome["applied"], bool)
                    and outcome["applied"] == 0
                ),
                "verified_zero": (
                    isinstance(outcome["verified"], int)
                    and not isinstance(outcome["verified"], bool)
                    and outcome["verified"] == 0
                ),
                "rejection_evidence": rejection_evidence,
                "dry_run_selected_action": dry_has_selected_plan,
                "reanalysis_matches_declared": (
                    isinstance(validation, dict)
                    and validation.get("matches_declared") is True
                ),
                "fresh_candidate_unsafe": (
                    isinstance(validation, dict)
                    and validation.get("fresh_candidate_safe") is False
                    and validation.get("status") == "REANALYSIS_GATE_REJECTED"
                ),
                "bytes_unchanged": False,
            }
            app.source_after = file_hashes(app.positive_paths)
            refusal["bytes_unchanged"] = app.source_after == app.source_before
            refusal["observed_refusal"] = all(
                refusal[key]
                for key in (
                    "returncode_nonzero",
                    "invocation_not_timed_out",
                    "invocation_without_error",
                    "written_false",
                    "applied_zero",
                    "verified_zero",
                    "rejection_evidence",
                    "dry_run_selected_action",
                    "fresh_candidate_unsafe",
                    "bytes_unchanged",
                )
            )
            app.record["checks"]["reanalysis_apply_refusal"] = refusal
            if refusal["observed_refusal"]:
                app.explicit_status = "safety_refused"
            else:
                app.fail("declared reanalysis gate did not refuse the unsafe apply")
        else:
            if isinstance(multi_control, dict):
                cli = multi_control.get("cli")
                if not isinstance(cli, dict):
                    app.fail("multi_finding_control is missing its cli expectations")
                    cli = {}
                expected_values = {
                    "exit_code": cli.get("apply_exit_code"),
                    "applied": cli.get("apply_applied"),
                    "skipped": cli.get("apply_skipped"),
                    "verified": cli.get("apply_verified"),
                    "unverified": cli.get("apply_unverified"),
                    "regressions": cli.get("apply_regressions"),
                }
                if not all(
                    isinstance(value, int) and not isinstance(value, bool)
                    for value in expected_values.values()
                ):
                    app.fail("multi_finding_control apply expectations must be integers")
                app.record["checks"]["multi_finding_apply"] = {
                    "expected": expected_values,
                    "observed": {
                        key: outcome.get(key)
                        for key in expected_values
                    },
                }
                for key, expected_value in expected_values.items():
                    observed_value = outcome.get(key)
                    if observed_value != expected_value:
                        app.fail(
                            "fix-apply: multi-finding control expected "
                            f"{key}={expected_value!r}, got {observed_value!r}"
                        )
                if outcome["written"] is not True:
                    app.fail("fix-apply did not report a written file")
            else:
                if applied.get("returncode") != 0:
                    app.fail(f"fix-apply: expected exit code 0, got {applied.get('returncode')!r}")
                if outcome["written"] is not True:
                    app.fail("fix-apply did not report a written file")
                if not isinstance(outcome["applied"], int) or outcome["applied"] < 1:
                    app.fail("fix-apply reported no applied rule fix")
                if outcome["verified"] != outcome["applied"] or outcome["unverified"] not in {0, None} or outcome["regressions"] not in {0, None}:
                    app.fail("fix-apply did not independently verify the applied action")
            app.source_after = file_hashes(app.positive_paths)
        app.record["checks"]["final_hashes"] = app.source_after
        if not app.source_after:
            app.fail("fix-apply did not produce final source hashes")
        try:
            final_source = target.read_bytes().decode("utf-8")
        except (OSError, UnicodeDecodeError) as exc:
            app.fail(f"cannot read final target source: {exc}")
            final_source = ""
        provider_final_hash = sha256_bytes(final_source.encode("utf-8"))
        candidate_hash = sha256_bytes(projected.encode("utf-8"))
        app.record["checks"]["final_source"] = {
            "path": relpath(target, self.output_root),
            "source": final_source,
            "sha256": provider_final_hash,
            "provider_final_hash": provider_final_hash,
            "candidate_hash": candidate_hash,
            "provider_matches_candidate": final_source == projected,
            "matches_projection": final_source == projected,
            "matches_initial": final_source == source,
            "reanalysis_gate_rejected": reanalysis_gate_rejected,
        }
        if reanalysis_gate_rejected:
            if final_source != source:
                app.fail("reanalysis-gated apply changed bytes instead of preserving the original source")
        elif final_source != projected:
            app.fail("fix-apply final bytes differ from the native projection")
        if (
            app.row.get("_native_reference_projection_mismatch") is True
            and final_source == projected
        ):
            app.record["checks"]["reference_projection"] = {
                "status": "reference_different",
                "reference_source": expected,
                "reference_source_sha256": (
                    sha256_bytes(expected.encode("utf-8"))
                    if isinstance(expected, str)
                    else None
                ),
                "candidate_source": projected,
                "candidate_source_sha256": candidate_hash,
                "provider_final_source_sha256": provider_final_hash,
                "provider_matches_candidate": final_source == projected,
                "equivalent": False,
            }
            app.explicit_status = "reference_different"
        if app.language == "csharp":
            positive = selected_csharp_positive_case(app.row, app.action_id)
            provenance = positive.get("reference_provenance") if isinstance(positive, dict) else None
            if isinstance(provenance, dict):
                expected_final_hash = provenance.get("final_source_sha256")
                provenance_check = app.record["checks"].get("reference_provenance")
                if not isinstance(provenance_check, dict):
                    provenance_check = {}
                    app.record["checks"]["reference_provenance"] = provenance_check
                reference_final_hash_matches = (
                    provider_final_hash == expected_final_hash
                    if isinstance(expected_final_hash, str) and expected_final_hash
                    else None
                )
                provenance_check["observed_final_source_sha256"] = provider_final_hash
                provenance_check["final_source_hash_matches"] = reference_final_hash_matches
                provenance_check["provider_final_hash"] = provider_final_hash
                provenance_check["candidate_hash"] = candidate_hash
                provenance_check["provider_matches_candidate"] = (
                    final_source == projected
                )
                provenance_check["reference_final_hash_matches"] = (
                    reference_final_hash_matches
                )
                if (
                    not reanalysis_gate_rejected
                    and reference_final_hash_matches is False
                ):
                    app.fail("CSharp final source hash does not match reference provenance")
        if isinstance(multi_control, dict):
            reference_fixall = multi_control.get("reference_fixall")
            if not isinstance(reference_fixall, dict):
                app.fail("multi_finding_control is missing reference_fixall provenance")
            else:
                artifact = reference_fixall.get("artifact")
                artifact_path = (
                    self.manifest_root / artifact
                    if isinstance(artifact, str) and not Path(artifact).is_absolute()
                    else None
                )
                observed_artifact_hash = sha256_file(artifact_path) if artifact_path else ""
                observed_final_hash = sha256_bytes(final_source.encode("utf-8"))
                observed_source_hash = sha256_bytes(source.encode("utf-8"))
                app.record["checks"]["reference_fixall"] = {
                    "artifact": artifact,
                    "selector": reference_fixall.get("selector"),
                    "expected_sha256": reference_fixall.get("sha256"),
                    "observed_sha256": observed_artifact_hash,
                    "source_sha256": observed_source_hash,
                    "expected_source_sha256": reference_fixall.get("source_sha256"),
                    "final_source_sha256": observed_final_hash,
                    "expected_final_source_sha256": reference_fixall.get("final_source_sha256"),
                    "diagnostic_count": reference_fixall.get("diagnostic_count"),
                }
                if observed_artifact_hash != reference_fixall.get("sha256"):
                    app.fail("multi-finding reference FixAll artifact hash does not match provenance")
                if observed_source_hash != reference_fixall.get("source_sha256"):
                    app.fail("multi-finding source bytes do not match reference FixAll provenance")
                if observed_final_hash != reference_fixall.get("final_source_sha256"):
                    app.fail("multi-finding final bytes do not match reference FixAll provenance")
                if reference_fixall.get("diagnostic_count") != multi_control.get("expected_finding_count"):
                    app.fail("multi-finding reference FixAll diagnostic count does not match control")
        _, final_report = self.run_analysis(app, "final-analyze", app.positive_paths)
        before_counts = issue_rule_counts(initial_report)
        after_counts = issue_rule_counts(final_report)
        target_before = before_counts.get(app.rule_key, 0)
        target_after = after_counts.get(app.rule_key, 0)
        regressions = {rule: count - before_counts.get(rule, 0) for rule, count in after_counts.items() if count > before_counts.get(rule, 0)}
        app.record["checks"]["analysis_reduction"] = {
            "before_counts": before_counts,
            "after_counts": after_counts,
            "target_before": target_before,
            "target_after": target_after,
            "regressions": regressions,
        }
        if isinstance(multi_control, dict):
            expected_finding_count = multi_control.get("expected_finding_count")
            expected_target_after = multi_control.get("expected_final_target_count")
            app.record["checks"]["multi_finding_counts"] = {
                "expected_target_before": expected_finding_count,
                "observed_target_before": target_before,
                "expected_target_after": expected_target_after,
                "observed_target_after": target_after,
            }
            if target_before != expected_finding_count:
                app.fail(
                    "multi-finding initial target count does not match declared "
                    f"finding count: expected {expected_finding_count!r}, got {target_before!r}"
                )
            if target_after != expected_target_after:
                app.fail(
                    "multi-finding final target count does not match declared "
                    f"count: expected {expected_target_after!r}, got {target_after!r}"
                )
        if not reanalysis_gate_rejected:
            if target_after >= target_before or target_before < 1:
                app.fail("final analyze did not reduce the targeted rule finding")
        if not reanalysis_gate_rejected and regressions:
            app.fail(f"final analyze introduced finding regressions: {regressions}")
        self.qualify_negative(app, automatic)

    def qualify_no_action(self, app: Application) -> None:
        if app.language == "python":
            ready = self.materialize_python(app)
        elif app.language in {"javascript", "typescript"}:
            ready = self.materialize_jsts(app)
        else:
            app.fail(f"no-action qualification is unsupported for {app.language!r}")
            return
        if not ready or app.unavailable:
            return
        app.semantic_args = self.semantic_args_for(app)
        _, report = self.run_analysis(app, "no-action-analyze", app.positive_paths)
        actionable: list[dict[str, Any]] = []
        for file_report, issue in find_issues(report, app.rule_key, app.workspace):
            if isinstance(issue.get("fix"), dict) or (
                isinstance(issue.get("alternatives"), list) and issue.get("alternatives")
            ):
                actionable.append({"path": file_report.get("path"), "range": issue.get("range")})
        app.record["checks"]["declared_no_action"] = {
            "actionable_findings": actionable,
            "expected_no_action": app.row.get("_expected_no_action"),
            "positive_finding_without_actions": app.row.get("_positive_finding_without_actions"),
        }
        if actionable:
            app.fail("manifest declares no actions but analyze exposed an actionable fix")
        dry = app.invoke_cli("no-action-fix-diff", self.fix_args(app.positive_paths, app, True, apply=False))
        if dry.get("returncode") not in {0, 1}:
            app.fail(f"no-action-fix-diff: unexpected exit code {dry.get('returncode')!r}")
        if plan_has_action(dry.get("parsed"), app.workspace, app.positive_paths):
            app.fail("manifest declares no actions but fix planned one")
        if app.row.get("_expected_no_action") is True:
            app.explicit_status = "no_action_expected"
        else:
            app.mark_unavailable("manifest declares no executable action for this positive fixture")

    def qualify_native_action_refusal(self, app: Application) -> None:
        """Exercise a proven invalid upstream projection as a native no-action."""
        if app.language not in {"javascript", "typescript"}:
            app.fail("native action refusal is only supported for JSTS")
            return
        metadata = app.row.get("_native_action_refusal_metadata")
        reference_action = app.row.get("_reference_action")
        if not isinstance(metadata, dict) or not isinstance(reference_action, dict):
            app.fail("native action refusal metadata is missing")
            return
        if metadata.get("native_action_id") is not None or metadata.get("native_available") is True:
            app.fail("native action refusal metadata claims a native action is available")
            return
        expected_projection = metadata.get("expected_source")
        if (
            not isinstance(expected_projection, str)
            or reference_action.get("expected_source") != expected_projection
        ):
            app.fail("native action refusal projection is not source-keyed to the reference action")
            return
        if not self.materialize_jsts(app):
            return
        if app.unavailable:
            return
        app.semantic_args = self.semantic_args_for(app)
        app.record["checks"]["semantic_args"] = list(app.semantic_args)
        target = app.target_path
        if target is None:
            app.fail("native action refusal has no target path")
            return
        try:
            source = target.read_text(encoding="utf-8", newline="")
        except TypeError:
            source = target.read_bytes().decode("utf-8")
        except OSError as exc:
            app.fail(f"cannot read native action refusal source: {exc}")
            return
        source_sha256 = metadata.get("source_sha256")
        source_matches = (
            isinstance(source_sha256, str)
            and sha256_bytes(source.encode("utf-8")) == source_sha256
        )
        if not source_matches:
            app.fail("native action refusal source hash does not match its overlay")
            return
        upstream_action_id = metadata.get("upstream_action_id")
        if upstream_action_id is not None and (
            not isinstance(upstream_action_id, str) or not upstream_action_id
        ):
            app.fail("native action refusal upstream action ID is malformed")
            return
        reference_action_ids = {
            value
            for value in (
                reference_action.get("upstream_action_id"),
                reference_action.get("native_action_id"),
                reference_action.get("manifest_native_action_id"),
            )
            if isinstance(value, str) and value
        }
        if upstream_action_id is not None and upstream_action_id not in reference_action_ids:
            app.fail("native action refusal upstream action is not source-keyed to the reference action")
            return
        parser_validity = reference_action.get("expected_source_parser_validity")
        parser_invalid = (
            isinstance(parser_validity, dict)
            and parser_validity.get("syntactically_valid") is False
        )
        upstream_invalid = metadata.get("upstream_invalid")
        if upstream_invalid is None:
            upstream_invalid = parser_invalid
        upstream_unsafe = metadata.get("upstream_unsafe")
        if upstream_unsafe is None:
            upstream_unsafe = False
        proof_check: dict[str, Any] = {
            "required": upstream_invalid is True and not parser_invalid,
            "path": None,
            "available": False,
            "source_hash_matches_projection": False,
            "compiler_exit": None,
            "diagnostic_codes": [],
            "expected_diagnostic_codes": metadata.get("compiler_error_ids"),
            "valid": False,
        }
        proof_paths = metadata.get("proof_paths")
        compiler_proof = (
            proof_paths.get("compiler")
            if isinstance(proof_paths, dict)
            else None
        )
        if isinstance(compiler_proof, str) and compiler_proof:
            proof_path = Path(compiler_proof)
            if not proof_path.is_absolute():
                proof_path = self.manifest_root / proof_path
            proof_check["path"] = str(proof_path)
            try:
                proof = json.loads(proof_path.read_bytes().decode("utf-8"))
            except (OSError, UnicodeDecodeError, json.JSONDecodeError):
                proof = None
            if isinstance(proof, dict):
                proof_source = proof.get("source")
                proof_source_sha256 = proof.get("source_sha256")
                proof_stdout = proof.get("compiler_stdout")
                proof_exit = proof.get("compiler_exit")
                diagnostics: list[Any] = []
                if isinstance(proof_stdout, str):
                    try:
                        compiler_payload = json.loads(proof_stdout)
                    except json.JSONDecodeError:
                        compiler_payload = None
                    if isinstance(compiler_payload, dict):
                        raw_diagnostics = compiler_payload.get("diagnostics")
                        if isinstance(raw_diagnostics, list):
                            diagnostics = raw_diagnostics
                codes = [
                    item.get("code")
                    for item in diagnostics
                    if isinstance(item, dict)
                    and isinstance(item.get("code"), int)
                    and not isinstance(item.get("code"), bool)
                ]
                expected_codes = metadata.get("compiler_error_ids")
                expected_codes_valid = (
                    isinstance(expected_codes, list)
                    and bool(expected_codes)
                    and all(
                        isinstance(code, int) and not isinstance(code, bool)
                        for code in expected_codes
                    )
                    and all(code in codes for code in expected_codes)
                )
                proof_check.update(
                    {
                        "available": True,
                        "source_hash_matches_projection": (
                            isinstance(proof_source, str)
                            and isinstance(proof_source_sha256, str)
                            and proof_source == expected_projection
                            and proof_source_sha256
                            == sha256_bytes(proof_source.encode("utf-8"))
                        ),
                        "compiler_exit": proof_exit,
                        "diagnostic_codes": codes,
                        "expected_diagnostic_codes_valid": expected_codes_valid,
                        "valid": (
                            isinstance(proof_exit, int)
                            and not isinstance(proof_exit, bool)
                            and proof_exit != 0
                            and bool(codes)
                            and (
                                expected_codes is None
                                or expected_codes_valid
                            )
                            and isinstance(proof_source, str)
                            and isinstance(proof_source_sha256, str)
                            and proof_source == expected_projection
                            and proof_source_sha256
                            == sha256_bytes(proof_source.encode("utf-8"))
                        ),
                    }
                )
        if (
            not isinstance(upstream_invalid, bool)
            or not isinstance(upstream_unsafe, bool)
            or (upstream_invalid is not True and upstream_unsafe is not True)
            or (upstream_unsafe is True and upstream_action_id is None)
            or (upstream_invalid is True and not parser_invalid and not proof_check["valid"])
        ):
            app.fail("native action refusal lacks a valid invalid/unsafe upstream classification")
            return
        app.record["checks"]["native_mapping"] = {
            "status": metadata.get("native_mapping_status"),
            "native_action_id": metadata.get("native_action_id"),
            "native_available": metadata.get("native_available"),
            "native_mapping_mismatch": metadata.get("native_mapping_mismatch"),
            "upstream_action_id": upstream_action_id,
            "upstream_invalid": upstream_invalid,
            "upstream_unsafe": upstream_unsafe,
            "compiler_proof": proof_check,
            "equivalent": False,
            "expected_upstream_projection": expected_projection,
            "expected_projection_parser_validity": parser_validity,
            "source_sha256": source_sha256,
            "source_matches_overlay": source_matches,
        }
        reference_fix = metadata.get("reference_fix")
        app.record["checks"]["upstream_projection"] = {
            "source_sha256": source_sha256,
            "projected": expected_projection,
            "projected_sha256": sha256_bytes(expected_projection.encode("utf-8")),
            "reference_fix": reference_fix,
            "parser_validity": parser_validity,
            "compiler_proof": proof_check,
            "equivalent": False,
            "upstream_invalid": upstream_invalid,
            "upstream_unsafe": upstream_unsafe,
        }
        _, report = self.run_analysis(app, "native-refusal-analyze", app.positive_paths)
        candidates = find_issues(report, app.rule_key, app.workspace, target)
        available_ids = sorted(
            {
                alternative.get("id")
                for _, issue in candidates
                for alternative in issue.get("alternatives", [])
                if isinstance(alternative, dict)
                and isinstance(alternative.get("id"), str)
            }
        )
        actionable = [
            {
                "path": file_report.get("path"),
                "range": issue.get("range"),
                "action_ids": [
                    alternative.get("id")
                    for alternative in issue.get("alternatives", [])
                    if isinstance(alternative, dict)
                ],
            }
            for file_report, issue in candidates
            if isinstance(issue.get("fix"), dict)
            or (
                isinstance(issue.get("alternatives"), list)
                and bool(issue.get("alternatives"))
            )
        ]
        if len(candidates) != 1:
            app.fail(
                f"native action refusal expected one target finding, found {len(candidates)}"
            )
            return
        unsafe_actionable = (
            actionable
            if upstream_action_id is None
            else [
                item
                for item in actionable
                if upstream_action_id in item.get("action_ids", [])
            ]
        )
        unexpected_action_ids = (
            available_ids
            if upstream_action_id is None
            else [value for value in available_ids if value == upstream_action_id]
        )
        if unexpected_action_ids:
            app.fail(
                f"native action refusal exposed unsafe action ids {unexpected_action_ids!r}"
            )
            return
        if unsafe_actionable:
            app.fail("native action refusal analyze exposed the unsafe upstream action")
            return
        def refusal_fix_args(apply: bool) -> list[str]:
            if upstream_action_id is None:
                return self.fix_args(app.positive_paths, app, True, apply=apply)
            args = [
                "--json",
                "fix",
                "--suggestion",
                f"{app.rule_key}={upstream_action_id}",
                "--diff",
            ]
            if apply:
                args.append("--apply")
            args.extend(app.semantic_args)
            args.extend(self.csharp_option_args(app))
            args.extend(relpath(path, app.workspace) for path in app.positive_paths)
            return args

        dry = app.invoke_cli(
            "native-refusal-fix-diff",
            refusal_fix_args(False),
        )
        dry_rows = selected_plan_rows(dry.get("parsed"), app.workspace, app.positive_paths)
        dry_fixes = plan_fix_entries(dry.get("parsed"), app.workspace, app.positive_paths)
        dry_before = file_hashes(app.positive_paths)
        dry_no_plan = not dry_fixes
        if dry.get("returncode") not in {0, 1}:
            app.fail(
                f"native action refusal fix-diff returned {dry.get('returncode')!r}"
            )
        if not dry_no_plan:
            app.fail("native action refusal fix-diff planned a fix")
        if dry_before != app.source_before:
            app.fail("native action refusal fix-diff modified source bytes")
        applied = app.invoke_cli(
            "native-refusal-fix-apply",
            refusal_fix_args(True),
        )
        apply_rows = selected_plan_rows(
            applied.get("parsed"), app.workspace, app.positive_paths
        )
        apply_row = apply_rows[0] if len(apply_rows) == 1 else {}
        outcome = {
            "returncode": applied.get("returncode"),
            "written": apply_row.get("written"),
            "applied": apply_row.get("applied"),
            "verified": apply_row.get("verified"),
            "unverified": apply_row.get("unverified"),
            "regressions": apply_row.get("regressions"),
            "skipped": apply_row.get("skipped"),
            "planned_fixes": len(plan_fix_entries(
                applied.get("parsed"), app.workspace, app.positive_paths
            )),
        }
        app.source_after = file_hashes(app.positive_paths)
        refusal = {
            "returncode_allowed": applied.get("returncode") in {0, 1},
            "invocation_not_timed_out": applied.get("timed_out") is False,
            "invocation_without_error": not applied.get("error"),
            "written_false": outcome["written"] is not True,
            "applied_zero": (
                outcome["applied"] is None
                or (
                    isinstance(outcome["applied"], int)
                    and not isinstance(outcome["applied"], bool)
                    and outcome["applied"] == 0
                )
            ),
            "verified_zero": (
                outcome["verified"] is None
                or (
                    isinstance(outcome["verified"], int)
                    and not isinstance(outcome["verified"], bool)
                    and outcome["verified"] == 0
                )
            ),
            "planned_fixes_zero": outcome["planned_fixes"] == 0,
            "bytes_unchanged": app.source_after == app.source_before,
        }
        refusal["observed_refusal"] = all(refusal.values())
        app.record["checks"]["native_action_refusal"] = {
            "status": metadata.get("native_mapping_status", "native_mapping_mismatch"),
            "equivalent": False,
            "upstream_invalid": upstream_invalid,
            "upstream_unsafe": upstream_unsafe,
            "upstream_action_id": upstream_action_id,
            "source_sha256": source_sha256,
            "expected_projection": expected_projection,
            "refusal_reason": metadata.get("native_mapping_mismatch")
            or "upstream action was safely withheld",
            "target_finding_count": len(candidates),
            "native_action_ids": available_ids,
            "actionable_findings": actionable,
            "dry_run": {
                "exit_code": dry.get("returncode"),
                "selected_plan_rows": len(dry_rows),
                "planned_fixes": len(dry_fixes),
                "source_unchanged": dry_before == app.source_before,
            },
            "apply": outcome,
            "refusal": refusal,
        }
        if not refusal["observed_refusal"]:
            app.fail("native action refusal did not preserve source bytes without a plan")
        else:
            app.explicit_status = "native_action_refusal"

    def load_jsts_derived_overlay(self) -> dict[str, Any] | None:
        """Load optional, source-keyed metadata derived from the frozen JSTS refs."""
        path = self.manifest_root / JSTS_DERIVED_OVERLAY
        if not path.is_file():
            return None
        try:
            raw = path.read_bytes()
            value = json.loads(raw.decode("utf-8"))
        except (OSError, UnicodeDecodeError, json.JSONDecodeError) as exc:
            self.top_failures.append(f"jsts derived overlay cannot be loaded {path}: {exc}")
            return None
        self.manifest_records["jsts-derived-overlay"] = {
            "path": str(path),
            "sha256": sha256_bytes(raw),
            "bytes": len(raw),
            "schema_version": value.get("schema_version") if isinstance(value, dict) else None,
        }
        if (
            not isinstance(value, dict)
            or value.get("schema_version") != SCHEMA_VERSION
            or value.get("kind") != "jsts-quickfix-derived-overlay"
        ):
            self.top_failures.append(
                f"jsts derived overlay {path} has an unsupported schema or kind"
            )
            return None
        for category in (
            "native_action_corrections",
            "native_action_gaps",
            "native_action_handoffs",
            "safety_refusals",
        ):
            entries = value.get(category, [])
            if not isinstance(entries, list):
                self.top_failures.append(
                    f"jsts derived overlay {path} field {category!r} is not an array"
                )
                continue
            for entry_index, entry in enumerate(entries):
                if not isinstance(entry, dict):
                    self.top_failures.append(
                        f"jsts derived overlay {path} {category}[{entry_index}] is not an object"
                    )
        return value

    @staticmethod
    def jsts_case_source(shared: dict[str, Any]) -> str | None:
        source = shared.get("source")
        if isinstance(source, str):
            return source
        project_files = shared.get("project_files")
        if isinstance(project_files, list):
            for item in project_files:
                if isinstance(item, dict) and isinstance(item.get("source"), str):
                    return item["source"]
        return None

    def jsts_overlay_matches(
        self,
        entry: dict[str, Any],
        shared: dict[str, Any],
        action: dict[str, Any],
        language: str,
        rule: str,
        action_count: int,
    ) -> bool:
        if entry.get("language") != language:
            return False
        entry_rule = entry.get("rule")
        if entry_rule not in {rule, f"{language}:{rule}"}:
            return False
        if entry.get("case_name") != shared.get("_case_name"):
            return False
        case_path = shared.get("path")
        if not isinstance(case_path, str):
            project_files = shared.get("project_files")
            if isinstance(project_files, list) and project_files and isinstance(project_files[0], dict):
                case_path = project_files[0].get("path")
        overlay_path = entry.get("case_path")
        if not isinstance(case_path, str) or not isinstance(overlay_path, str):
            return False
        if path_key(case_path) != path_key(overlay_path):
            return False
        source = self.jsts_case_source(shared)
        source_sha256 = entry.get("source_sha256")
        if (
            not isinstance(source, str)
            or not isinstance(source_sha256, str)
            or sha256_bytes(source.encode("utf-8")) != source_sha256
        ):
            return False
        case_reference = shared.get("_case_reference")
        if (
            not isinstance(case_reference, dict)
            or case_reference.get("source_sha256") != source_sha256
        ):
            return False
        overlay_project_files = entry.get("project_files")
        if isinstance(overlay_project_files, list) and overlay_project_files:
            project_files = shared.get("project_files")
            if not isinstance(project_files, list):
                return False
            for expected_file in overlay_project_files:
                if not isinstance(expected_file, dict):
                    return False
                expected_path = expected_file.get("path")
                expected_hash = expected_file.get("source_sha256")
                if not isinstance(expected_path, str) or not isinstance(expected_hash, str):
                    return False
                matches = [
                    item
                    for item in project_files
                    if isinstance(item, dict)
                    and isinstance(item.get("path"), str)
                    and path_key(item["path"]) == path_key(expected_path)
                ]
                if len(matches) != 1:
                    return False
                actual_file = matches[0]
                actual_source = actual_file.get("source")
                actual_hash = (
                    sha256_bytes(actual_source.encode("utf-8"))
                    if isinstance(actual_source, str)
                    else actual_file.get("source_sha256")
                )
                if actual_hash != expected_hash:
                    return False
        expected_action_ids = [
            value
            for value in (
                entry.get("action_id"),
                entry.get("manifest_native_action_id"),
                entry.get("upstream_action_id"),
                entry.get("native_action_id"),
            )
            if isinstance(value, str) and value
        ]
        native_action_id = action.get("native_action_id")
        if expected_action_ids:
            return native_action_id in expected_action_ids or (
                native_action_id is None and action_count == 1
            )
        return native_action_id is None and action_count == 1

    def apply_jsts_overlay(
        self,
        overlay: dict[str, Any],
        shared: dict[str, Any],
        actions: list[dict[str, Any]],
        language: str,
        rule: str,
        family: str,
        case_index: int,
    ) -> tuple[list[dict[str, Any]], dict[str, Any]]:
        """Apply only exact source/action overlays; unmatched entries remain failures."""
        overlay_categories = (
            ("native_action_handoffs", overlay.get("native_action_handoffs", [])),
            ("native_action_corrections", overlay.get("native_action_corrections", [])),
            ("native_action_gaps", overlay.get("native_action_gaps", [])),
            ("safety_refusals", overlay.get("safety_refusals", [])),
        )
        applied: dict[str, Any] = {}
        updated: list[dict[str, Any]] = []
        for action_index, raw_action in enumerate(actions):
            if not isinstance(raw_action, dict):
                continue
            action = dict(raw_action)
            matches: list[tuple[str, int, dict[str, Any]]] = []
            for category, entries in overlay_categories:
                if not isinstance(entries, list):
                    continue
                for entry_index, entry in enumerate(entries):
                    if isinstance(entry, dict) and self.jsts_overlay_matches(
                        entry,
                        shared,
                        action,
                        language,
                        rule,
                        len(actions),
                    ):
                        matches.append((category, entry_index, entry))
            compatible_handoff_gap = (
                any(category == "native_action_handoffs" for category, _, _ in matches)
                and any(category == "native_action_gaps" for category, _, _ in matches)
            )
            if len(matches) > 1 and not compatible_handoff_gap:
                self.top_failures.append(
                    f"jsts {family} {rule} case {case_index} action {action_index}: "
                    "derived overlay matches multiple incompatible records"
                )
            for category, entry_index, entry in matches:
                overlay_key = (
                    f"{category}[{entry_index}]::{language}:{rule}::"
                    f"{shared.get('_case_name')}::"
                    f"{shared.get('_case_reference', {}).get('source_sha256') if isinstance(shared.get('_case_reference'), dict) else None}::"
                    f"{action_index}"
                )
                applied[overlay_key] = {
                    "case_index": case_index,
                    "action_index": action_index,
                }
                if category == "native_action_handoffs":
                    action["native_action_id"] = entry.get("native_action_id")
                    action["native_action_gap"] = False
                    action["native_available"] = True
                    action["native_gap_reason"] = None
                    action["native_mapping_status"] = entry.get("native_mapping_status")
                    action["native_mapping_mismatch"] = entry.get("native_mapping_mismatch")
                    action["_native_action_handoff_pending"] = {
                        key: value for key, value in entry.items()
                    }
                elif category == "native_action_corrections":
                    action["native_action_id"] = entry.get("native_action_id")
                    action["native_action_gap"] = entry.get("native_action_gap", False)
                    action["native_available"] = entry.get("native_available")
                    action["native_gap_reason"] = entry.get("native_gap_reason")
                    action["native_mapping_status"] = entry.get("native_mapping_status")
                    action["native_mapping_mismatch"] = entry.get("native_mapping_mismatch")
                    if isinstance(entry.get("upstream_action_id"), str):
                        action["upstream_action_id"] = entry["upstream_action_id"]
                    if isinstance(entry.get("manifest_native_action_id"), str):
                        action["manifest_native_action_id"] = entry["manifest_native_action_id"]
                    action["_native_action_correction"] = {
                        key: value for key, value in entry.items()
                    }
                    if (
                        entry.get("native_action_id") is None
                        and entry.get("native_action_gap") is False
                        and entry.get("native_mapping_status") == "native_mapping_mismatch"
                    ):
                        action["_native_action_refusal"] = True
                        action["_native_action_refusal_metadata"] = {
                            key: value for key, value in entry.items()
                        }
                elif category == "native_action_gaps" and not any(
                    other_category == "native_action_handoffs"
                    for other_category, _, _ in matches
                ):
                    action["native_action_id"] = None
                    action["native_action_gap"] = True
                    action["native_available"] = False
                    action["native_gap_reason"] = entry.get("native_gap_reason")
                    if isinstance(entry.get("upstream_action_id"), str):
                        action["upstream_action_id"] = entry["upstream_action_id"]
                    if isinstance(entry.get("manifest_native_action_id"), str):
                        action["manifest_native_action_id"] = entry["manifest_native_action_id"]
                elif category == "safety_refusals":
                    projected = entry.get("projected_reanalysis")
                    target_before = projected.get("target_before") if isinstance(projected, dict) else None
                    target_after = projected.get("target_after") if isinstance(projected, dict) else None
                    increased = projected.get("increased") if isinstance(projected, dict) else None
                    if (
                        not isinstance(target_before, int)
                        or isinstance(target_before, bool)
                        or target_before < 0
                        or not isinstance(target_after, int)
                        or isinstance(target_after, bool)
                        or target_after < 0
                        or not isinstance(increased, dict)
                        or not increased
                        or not all(
                            isinstance(key, str)
                            and key
                            and isinstance(value, int)
                            and not isinstance(value, bool)
                            and value >= 1
                            for key, value in increased.items()
                        )
                    ):
                        self.top_failures.append(
                            f"jsts {family} {rule} case {case_index} action {action_index}: "
                            "derived safety refusal has malformed projected reanalysis"
                        )
                        continue
                    action["reanalysis"] = {
                        "status": "REANALYSIS_GATE_REJECTED",
                        "target_reduced": target_after < target_before,
                        "increased": dict(increased),
                        "reason": entry.get("refusal_reason")
                        or "Applying the native action introduces additional findings; verifier refusal is retained.",
                        "expectation_only": True,
                        "derived_overlay": {
                            "kind": entry.get("kind"),
                            "proof_paths": entry.get("proof_paths"),
                            "projected_reanalysis": dict(projected),
                        },
                    }
                    action["_native_safety_refusal"] = {
                        key: value for key, value in entry.items()
                    }
            updated.append(action)
        return updated, applied

    def load_jsts_reference_manifests(self) -> list[dict[str, Any]]:
        """Load and flatten live JSTS reference arrays at execution time."""
        overlay = self.load_jsts_derived_overlay()
        overlay_applied: dict[str, dict[str, Any]] = {}
        paths = {
            "expressions": self.manifest_root / "jsts-quickfix-expressions.reference.json",
            "typed": self.manifest_root / "jsts-quickfix-typed.reference.json",
        }
        families = ("expressions", "typed")
        flattened: list[dict[str, Any]] = []
        for family in families:
            path = paths[family]
            if not path.is_file():
                self.top_failures.append(
                    f"jsts {family}: live reference manifest is unavailable; expected {path}"
                )
                continue
            try:
                raw = path.read_bytes()
                value = json.loads(raw.decode("utf-8"))
            except (OSError, UnicodeDecodeError, json.JSONDecodeError) as exc:
                self.top_failures.append(f"jsts {family}: cannot load live reference manifest {path}: {exc}")
                continue
            self.manifest_records[f"jsts-{family}"] = {
                "path": str(path),
                "sha256": sha256_bytes(raw),
                "bytes": len(raw),
                "rows": len(value) if isinstance(value, list) else None,
            }
            if not isinstance(value, list):
                self.top_failures.append(f"jsts {family}: live reference manifest is not an array")
                continue
            if not value:
                self.top_failures.append(f"jsts {family}: manifest is empty")
            for group_index, group in enumerate(value):
                if not isinstance(group, dict):
                    self.top_failures.append(f"jsts {family} group {group_index}: expected object")
                    continue
                rule = group.get("rule")
                raw_languages = group.get("languages")
                if raw_languages is None:
                    raw_language = group.get("language")
                    raw_languages = [raw_language] if raw_language is not None else None
                languages = raw_languages
                cases = group.get("cases")
                if (
                    not isinstance(rule, str)
                    or not isinstance(languages, list)
                    or not languages
                    or not isinstance(cases, list)
                    or not cases
                ):
                    self.top_failures.append(f"jsts {family} group {group_index}: malformed rule/language/cases")
                    continue
                for case_index, case in enumerate(cases):
                    if not isinstance(case, dict):
                        self.top_failures.append(f"jsts {family} {rule} case {case_index}: expected object")
                        continue
                    if case.get("reference_status") != "REFERENCE_EXECUTED":
                        self.top_failures.append(
                            f"jsts {family} {rule} case {case_index}: reference execution is not confirmed"
                        )
                        continue
                    source_sha256 = case.get("source_sha256")
                    if (
                        not isinstance(source_sha256, str)
                        or re.fullmatch(r"[0-9a-fA-F]{64}", source_sha256) is None
                    ):
                        self.top_failures.append(
                            f"jsts {family} {rule} case {case_index}: missing or malformed source_sha256"
                        )
                        continue
                    source = case.get("source")
                    project_files = case.get("project_files")
                    if not isinstance(source, str) and not (
                        isinstance(project_files, list)
                        and project_files
                        and isinstance(project_files[0], dict)
                        and isinstance(project_files[0].get("source"), str)
                    ):
                        self.top_failures.append(f"jsts {family} {rule} case {case_index}: no source text")
                        continue
                    actions = case.get("actions")
                    if not isinstance(actions, list):
                        self.top_failures.append(f"jsts {family} {rule} case {case_index}: actions is not an array")
                        continue
                    case_language = case.get("language")
                    if isinstance(case_language, str):
                        case_languages = [LANGUAGE_ALIASES.get(case_language.lower(), case_language)]
                    else:
                        case_path = case.get("path") or case.get("source_path")
                        if not isinstance(case_path, str) and isinstance(project_files, list) and project_files:
                            first_file = project_files[0]
                            case_path = first_file.get("path") if isinstance(first_file, dict) else None
                        suffix = Path(case_path).suffix.lower() if isinstance(case_path, str) else ""
                        inferred = {
                            ".js": "javascript",
                            ".jsx": "javascript",
                            ".mjs": "javascript",
                            ".cjs": "javascript",
                            ".ts": "typescript",
                            ".tsx": "typescript",
                            ".mts": "typescript",
                            ".cts": "typescript",
                        }.get(suffix)
                        if inferred is None:
                            self.top_failures.append(f"jsts {family} {rule} case {case_index}: cannot infer case language")
                            continue
                        case_languages = [inferred]
                    if not all(language in {"javascript", "typescript"} for language in case_languages):
                        self.top_failures.append(f"jsts {family} {rule} case {case_index}: unsupported case language")
                        continue
                    shared: dict[str, Any] = {
                        "rule": rule,
                        "languages": case_languages,
                        "source": source,
                        "path": case.get("path") or case.get("source_path"),
                        "project_files": project_files,
                        "negative": case.get("negative"),
                        "_reference_manifest": str(path),
                        "_reference_family": family,
                        "_case_name": case.get("name"),
                        "_case_reference": {
                            key: value
                            for key, value in case.items()
                            if key not in {"actions", "source", "project_files", "negative"}
                        },
                    }
                    case_actions = actions
                    case_overlay_applied: dict[str, dict[str, Any]] = {}
                    if overlay is not None:
                        case_actions, case_overlay_applied = self.apply_jsts_overlay(
                            overlay,
                            shared,
                            actions,
                            case_languages[0],
                            rule,
                            family,
                            case_index,
                        )
                        overlay_applied.update(case_overlay_applied)
                    if case_overlay_applied:
                        shared["_derived_overlay"] = case_overlay_applied
                    if case_actions:
                        for action_index, action in enumerate(case_actions):
                            if not isinstance(action, dict):
                                self.top_failures.append(
                                    f"jsts {family} {rule} case {case_index} action {action_index}: expected object"
                                )
                                continue
                            reference_shape = reference_fix_shape(action.get("reference_fix"))
                            if reference_shape is None:
                                self.top_failures.append(
                                    f"jsts {family} {rule} case {case_index} action {action_index}: "
                                    "reference_fix lacks concrete edits or range/text projection"
                                )
                                continue
                            mode = action.get("mode")
                            action_id = action.get("native_action_id")
                            native_gap = (
                                mode == "suggestion"
                                and action_id is None
                                and action.get("native_action_gap") is True
                                and action.get("native_available") is False
                            )
                            native_refusal = (
                                mode == "suggestion"
                                and action_id is None
                                and action.get("_native_action_refusal") is True
                            )
                            native_reference_projection_mismatch = (
                                isinstance(action.get("_native_action_correction"), dict)
                                and action.get("native_mapping_status")
                                == "native_mapping_mismatch"
                                and isinstance(action_id, str)
                                and bool(action_id)
                            )
                            if mode == "automatic":
                                if action_id is not None:
                                    self.top_failures.append(
                                        f"jsts {family} {rule} case {case_index} action {action_index}: "
                                        "automatic native_action_id must be omitted or null"
                                    )
                                    continue
                            elif not isinstance(action_id, str) or not action_id:
                                if not native_gap and not native_refusal:
                                    self.top_failures.append(
                                        f"jsts {family} {rule} case {case_index} action {action_index}: "
                                        "missing native_action_id"
                                    )
                                    continue
                            row = dict(shared)
                            row.update(
                                {
                                    "action_ids": [action_id],
                                    "automatic": action.get("mode") == "automatic",
                                    "expected": action.get("expected_source"),
                                    "_reference_action": action,
                                    "_action_index": action_index,
                                    "_reference_fix_shape": reference_shape,
                                    "_native_action_gap": native_gap,
                                    "_native_action_refusal": native_refusal,
                                    "_native_action_refusal_metadata": action.get(
                                        "_native_action_refusal_metadata"
                                    ),
                                    "_native_action_handoff": action.get(
                                        "_native_action_handoff_pending"
                                    ),
                                    "_native_safety_refusal": action.get(
                                        "_native_safety_refusal"
                                    ),
                                    "_native_action_correction": action.get(
                                        "_native_action_correction"
                                    ),
                                    "_native_reference_projection_mismatch": (
                                        native_reference_projection_mismatch
                                    ),
                                }
                            )
                            flattened.append(row)
                    elif (
                        case.get("expected_no_action") is True
                        or case.get("positive_finding_without_actions") is True
                    ):
                        row = dict(shared)
                        row.update(
                            {
                                "action_ids": [],
                                "automatic": False,
                                "expected": None,
                                "_expected_no_action": True,
                                "_positive_finding_without_actions": case.get("positive_finding_without_actions") is True,
                            }
                        )
                        flattened.append(row)
                    else:
                        self.top_failures.append(
                            f"jsts {family} {rule} case {case_index}: no actions or expected_no_action control"
                        )
        if overlay is not None:
            for category in (
                "native_action_handoffs",
                "native_action_corrections",
                "native_action_gaps",
                "safety_refusals",
            ):
                entries = overlay.get(category, [])
                if not isinstance(entries, list):
                    continue
                for entry_index, entry in enumerate(entries):
                    if (
                        not isinstance(entry, dict)
                        or (
                            self.language is not None
                            and entry.get("language") != self.language
                        )
                    ):
                        continue
                    prefix = f"{category}[{entry_index}]::"
                    if not any(key.startswith(prefix) for key in overlay_applied):
                        self.top_failures.append(
                            f"jsts derived overlay {category}[{entry_index}] did not match "
                            "a loaded source/action identity"
                        )
        return flattened

    def run_python(self) -> None:
        rows = self.load_manifest(PYTHON_MANIFEST, "python")
        for index, row in enumerate(rows):
            rule_key = str(row.get("key", ""))
            if not rule_key:
                self.top_failures.append(f"python row {index}: missing key")
                continue
            actions = row.get("actions")
            if not isinstance(actions, list):
                self.top_failures.append(f"python row {index} {rule_key}: actions is not a list")
                continue
            if not actions:
                if self.rule_selected("python", row, rule_key):
                    app = Application(self, "python", index, rule_key, None, "no_action", row)
                    self.qualify_no_action(app)
                    self.applications.append(app.finalize())
                continue
            for action in actions:
                if not isinstance(action, dict) or not isinstance(action.get("id"), str):
                    self.top_failures.append(f"python row {index} {rule_key}: malformed action")
                    continue
                action_id = action["id"]
                if not self.rule_selected("python", row, rule_key):
                    continue
                app = Application(self, "python", index, rule_key, action_id, str(action.get("mode") or "suggestion"), row)
                if action.get("mode") != "suggestion":
                    app.mark_unavailable(f"unsupported Python action mode: {action.get('mode')!r}")
                else:
                    self.qualify_action(app, automatic=False)
                self.applications.append(app.finalize())

    def run_jsts(self) -> None:
        rows = self.load_jsts_reference_manifests()
        for index, row in enumerate(rows):
            rule = row.get("rule")
            languages = row.get("languages")
            action_ids = row.get("action_ids")
            if not isinstance(rule, str) or not isinstance(languages, list) or not isinstance(action_ids, list):
                self.top_failures.append(f"jsts row {index}: malformed flattened reference row")
                continue
            for raw_language in languages:
                language = LANGUAGE_ALIASES.get(str(raw_language).lower())
                if language not in {"javascript", "typescript"}:
                    self.top_failures.append(f"jsts row {index} {rule}: unsupported language {raw_language!r}")
                    continue
                if self.language is not None and language != self.language:
                    continue
                rule_key = f"{language}:{rule}"
                if not self.rule_selected(language, row, rule_key):
                    continue
                reference_action = row.get("_reference_action")
                mode = reference_action.get("mode") if isinstance(reference_action, dict) else None
                automatic = mode == "automatic"
                if not automatic and not action_ids:
                    app = Application(self, language, index, rule_key, None, "no_action", row)
                    if row.get("_expected_no_action") is not True:
                        app.mark_unavailable("expected_no_action control is missing or not true")
                    else:
                        self.qualify_no_action(app)
                    self.applications.append(app.finalize())
                    continue
                if automatic:
                    if action_ids != [None]:
                        self.top_failures.append(
                            f"jsts row {index} {rule}: automatic row must contain a null native action id"
                        )
                        continue
                    action_id = None
                elif row.get("_native_action_refusal") is True:
                    if action_ids != [None]:
                        self.top_failures.append(
                            f"jsts row {index} {rule}: native action refusal must preserve a null native action id"
                        )
                        continue
                    action_id = None
                elif row.get("_native_action_gap") is True:
                    if action_ids != [None]:
                        self.top_failures.append(
                            f"jsts row {index} {rule}: native action gap must preserve a null native action id"
                        )
                        continue
                    action_id = None
                elif len(action_ids) != 1 or not isinstance(action_ids[0], str):
                    self.top_failures.append(f"jsts row {index} {rule}: flattened row must contain one native action id")
                    continue
                else:
                    action_id = action_ids[0]
                app = Application(self, language, index, rule_key, action_id, str(mode or "unknown"), row)
                handoff = row.get("_native_action_handoff")
                if isinstance(handoff, dict):
                    app.record["checks"]["native_action_handoff"] = {
                        "status": "pending_native_validation",
                        "native_action_id": handoff.get("native_action_id"),
                        "source_sha256": handoff.get("source_sha256"),
                        "case_name": handoff.get("case_name"),
                        "implementation_status": handoff.get(
                            "implementation_status",
                            "handed_off_pending_native_validation",
                        ),
                    }
                if row.get("_native_action_refusal") is True:
                    if mode != "suggestion":
                        app.fail("native action refusal must use suggestion mode")
                    else:
                        self.qualify_native_action_refusal(app)
                elif row.get("_native_action_gap") is True:
                    reason = (
                        reference_action.get("native_gap_reason")
                        if isinstance(reference_action, dict)
                        else None
                    ) or "reference action has no native implementation"
                    app.record["checks"]["native_action_gap"] = {
                        "unresolved": True,
                        "native_action_id": None,
                        "native_available": (
                            reference_action.get("native_available")
                            if isinstance(reference_action, dict)
                            else False
                        ),
                        "upstream_action_id": (
                            reference_action.get("upstream_action_id")
                            if isinstance(reference_action, dict)
                            else None
                        ),
                        "upstream_suggestion": (
                            reference_action.get("upstream_suggestion")
                            if isinstance(reference_action, dict)
                            else None
                        ),
                        "reason": reason,
                    }
                    app.fail(f"native action gap unresolved: {reason}")
                elif mode not in {"suggestion", "automatic"}:
                    app.mark_unavailable(f"unsupported JSTS reference action mode: {mode!r}")
                else:
                    self.qualify_action(app, automatic=automatic)
                    safety_metadata = row.get("_native_safety_refusal")
                    if isinstance(safety_metadata, dict):
                        refusal_check = app.record["checks"].get("reanalysis_apply_refusal")
                        validation_check = app.record["checks"].get("reanalysis_validation")
                        fresh_safe = (
                            isinstance(validation_check, dict)
                            and validation_check.get("fresh_candidate_safe") is True
                            and validation_check.get("status") == "REANALYSIS_ACCEPTED"
                        )
                        fresh_unsafe = (
                            isinstance(validation_check, dict)
                            and validation_check.get("fresh_candidate_safe") is False
                            and validation_check.get("status") == "REANALYSIS_GATE_REJECTED"
                        )
                        refusal_observed = (
                            isinstance(refusal_check, dict)
                            and refusal_check.get("observed_refusal") is True
                        )
                        safety_passed = (
                            not app.failures
                            and (
                                (fresh_safe and not refusal_observed)
                                or (fresh_unsafe and refusal_observed)
                            )
                        )
                        if fresh_safe:
                            current_status = "accepted_current"
                        elif fresh_unsafe:
                            current_status = "safety_refused"
                        else:
                            current_status = "fail"
                        app.record["checks"]["native_safety_refusal"] = {
                            "status": current_status if safety_passed else "fail",
                            "native_action_id": safety_metadata.get("native_action_id"),
                            "source_sha256": safety_metadata.get("source_sha256"),
                            "projected_reanalysis": safety_metadata.get("projected_reanalysis"),
                            "refusal_reason": safety_metadata.get("refusal_reason"),
                            "equivalent": False,
                            "historical_matches": (
                                validation_check.get("matches_declared")
                                if isinstance(validation_check, dict)
                                else None
                            ),
                            "fresh_candidate_safe": fresh_safe,
                            "fresh_candidate_unsafe": fresh_unsafe,
                            "refusal_observed": refusal_observed,
                            "checks_passed": safety_passed,
                        }
                        if fresh_unsafe and not safety_passed:
                            app.fail("derived safety refusal checks did not pass")
                        elif not fresh_safe and not fresh_unsafe:
                            app.fail("fresh safety reanalysis did not produce an accepted or refused decision")
                self.applications.append(app.finalize())

    def run_csharp(self) -> None:
        rows = self.load_manifest(CSHARP_MANIFEST, "csharp")
        for index, row in enumerate(rows):
            rule = row.get("rule")
            target_rule = row.get("target_rule")
            action_ids = row.get("action_ids")
            if not isinstance(rule, str) or not isinstance(target_rule, str) or not isinstance(action_ids, list):
                self.top_failures.append(f"csharp row {index}: malformed rule/action metadata")
                continue
            if not action_ids:
                self.top_failures.append(f"csharp row {index} {target_rule}: no action ids declared")
                continue
            rule_key = target_rule
            positives = row.get("positive_cases")
            if not isinstance(positives, list):
                self.top_failures.append(f"csharp row {index} {rule_key}: positive_cases is not a list")
                continue
            for action_id in action_ids:
                if not isinstance(action_id, str):
                    self.top_failures.append(f"csharp row {index} {rule_key}: malformed action id")
                    continue
                if not self.rule_selected("csharp", row, rule_key):
                    continue
                app = Application(self, "csharp", index, rule_key, action_id, "suggestion", row)
                self.qualify_action(app, automatic=False)
                self.applications.append(app.finalize())

    def run(self) -> int:
        if self.language in {None, "python"}:
            self.run_python()
        if self.language in {None, "javascript", "typescript"}:
            self.run_jsts()
        if self.language in {None, "csharp"}:
            self.run_csharp()
        if self.selectors and not self.applications:
            self.top_failures.append("rule selector matched no runnable manifest row/action")
        summary = {
            "applications": len(self.applications),
            "pass": sum(item.get("status") == "pass" for item in self.applications),
            "fail": sum(item.get("status") == "fail" for item in self.applications),
            "native_action_refusal": sum(
                item.get("status") == "native_action_refusal"
                for item in self.applications
            ),
            "safety_refused": sum(
                item.get("status") == "safety_refused"
                for item in self.applications
            ),
            "native_action_gap": sum(
                isinstance(item.get("checks"), dict)
                and isinstance(item["checks"].get("native_action_gap"), dict)
                and item["checks"]["native_action_gap"].get("unresolved") is True
                for item in self.applications
            ),
            "unavailable": sum(item.get("status") == "unavailable" for item in self.applications),
            "no_action_declared": sum(item.get("status") == "no_action_declared" for item in self.applications),
            "no_action_expected": sum(item.get("status") == "no_action_expected" for item in self.applications),
        }
        result = {
            "schema_version": SCHEMA_VERSION,
            "binary": {"path": str(self.binary), "sha256": sha256_file(self.binary)},
            "arguments": {
                "language": self.language,
                "rule": self.selectors,
                "timeout_seconds": self.timeout,
                "output": str(self.output_root),
            },
            "manifests": self.manifest_records,
            "prerequisites": {
                "typescript_module": str(self.typescript_module) if self.typescript_module else None,
                "typescript_module_sha256": sha256_file(self.typescript_module / "package.json") if self.typescript_module else None,
                "typescript_base": str(self.typescript_base) if self.typescript_base else None,
                "dotnet": str(self.dotnet) if self.dotnet else None,
                "offline_nuget_config": str(self.manifest_root / "helper-smoke" / "NuGet.Config"),
            },
            "applications": self.applications,
            "summary": summary,
            "failures": self.top_failures,
            "ok": (
                not self.top_failures
                and summary["fail"] == 0
                and summary["unavailable"] == 0
                and summary["native_action_gap"] == 0
            ),
        }
        write_json(self.output_root / "result.json", result)
        return 0 if result["ok"] else 1


def argument_parser() -> argparse.ArgumentParser:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--binary", required=True, help="absolute path to the actual hoonarqube CLI executable")
    parser.add_argument("--language", help="optional language slice: python, javascript, typescript, or csharp")
    parser.add_argument("--rule", action="append", default=[], help="optional rule selector; repeat or comma-separate")
    parser.add_argument("--output", required=True, help="result directory to create")
    parser.add_argument("--timeout", type=int, default=DEFAULT_TIMEOUT_SECONDS, help="per-process timeout in seconds (default: 90)")
    return parser


def main(argv: list[str] | None = None) -> int:
    parser = argument_parser()
    args = parser.parse_args(argv)
    if args.timeout <= 0:
        parser.error("--timeout must be positive")
    try:
        harness = Harness(args)
        return harness.run()
    except HarnessError as exc:
        output = Path(args.output).expanduser()
        try:
            output.mkdir(parents=True, exist_ok=True)
            write_json(
                output / "result.json",
                {
                    "schema_version": SCHEMA_VERSION,
                    "ok": False,
                    "failures": [str(exc)],
                    "summary": {
                        "applications": 0,
                        "pass": 0,
                        "fail": 1,
                        "native_action_gap": 0,
                        "unavailable": 0,
                        "no_action_declared": 0,
                        "no_action_expected": 0,
                    },
                },
            )
        except OSError:
            pass
        print(f"quickfix smoke harness: {exc}", file=sys.stderr)
        return 2


if __name__ == "__main__":
    raise SystemExit(main())
